INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('steveclarke/kiso/contributing', 'contributing', 'steveclarke', 'kiso', 'community', 'contributing steveclarke kiso community Contributing是一个基于Shadcn/UI的Rails UI组件，使用ERB部分、Tailwind CSS和进阶Stimulus ContributingはShadcn/UIをインスパイアしたRails UIコンポーネントで、ERBパーシャル、Tailwind CSS、進歩的なStimulusを使用しています Contributing은 Shadcn/UI에서 영감을 받은 Rails UI 컴포넌트로, ERB 부분, Tailwind CSS, 점진적인 Stimulus를 사용합니다 Componentes UI de Rails con tecnologías como ERB, Tailwind CSS y Stimulus para la contribución de AI Composants UI Rails avec des technologies comme ERB, Tailwind CSS et Stimulus pour la contribution IA Rails-UI-Komponenten mit Technologien wie ERB, Tailwind CSS und Stimulus für die AI-Beiträge Rails UI components inspirados em shadcn/ui, utilizando ERB, Tailwind CSS e Stimulus para uma experiência de usuário progressiva Компоненты пользовательского интерфейса Rails, вдохновленные shadcn/ui, использующие ERB, Tailwind CSS и Stimulus для прогрессивного опыта пользователя مكونات واجهة المستخدم للريلز الملهمة من شادسن/يوي، باستخدام إر بي وتيلويند سي إس وستيمولوس من أجل تجربة مستخدم متقدمة Rails UI components inspired by shadcn/ui — ERB partials, Tailwind CSS, progressive Stimulus 如何使用Contributing 什么是Shadcn/UI Rails UI组件 Tailwind CSS教程 Stimulus入门 Contributing安装 Contributing设置指南 Rails UI components inspired by shadcn/ui — ERB partials, Tailwind CSS, progressive Stimulus');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('inno-se-toolkit/se-toolkit-lab-4/review-via-conventions', 'community', 'inno-se-toolkit', 'se-toolkit-lab-4', 'inno-se-toolkit/se-toolkit-lab-4', 'review-via-conventions', 0, 242, 36, '2026-03-03T09:39:19Z', '2026-03-04T15:37:58.451Z', '640b9f10506223976f97967a4e5b494ea882580c18ee5c9e38ff84df61112cb9', '{"id":"inno-se-toolkit/se-toolkit-lab-4/review-via-conventions","name":"review-via-conventions","description":{"zh":"review-via-conventions技能用于Lab 04的测试、前端和AI工具开发，实现高效的代码审查","ja":"review-via-conventionsスキルは、Lab 04のテスト、フロントエンド、AIエージェント開発で使用され、効率的なコードレビューを実現します","ko":"review-via-conventions 스킬은 Lab 04의 테스트, 프론트엔드, AI 에이전트 개발에서 사용되어 효율적인 코드 리뷰를 구현합니다","es":"La revisión mediante convenciones es una habilidad de los agentes de AI que permite mejorar la calidad del código y la eficiencia del desarrollo","fr":"La revue via conventions est une compétence des agents d''IA qui permet d''améliorer la qualité du code et l''efficacité du développement","de":"Die Review via Konventionen ist eine Fähigkeit der KI-Tools, die die Code-Qualität und die Entwicklungs-Effizienz verbessert","pt":"A habilidade de review-via-convenções permite testar e validar a integração de front-end e agentes de IA de forma eficiente","ru":"Навык проверки через конвенции позволяет тестировать и проверять интеграцию фронтенда и ИИ Агентов эффективно","ar":"تمكنك مهارة المراجعة من خلال الاتفاقيات من اختبار وتحقق دمج الواجهة الأمامية وأدوات الذكاء الاصطناعي بفعالية","en":"Lab 04 — Testing, Front-end, and AI Agents"},"seo":{"title":{"zh":"AI工具review-via-conventions技能","ja":"AIエージェントreview-via-conventions","ko":"AI 에이전트 review-via-conventions","es":"Herramientas de AI: Revisión mediante convenciones","fr":"Outils d''IA: Revue via conventions","de":"KI-Tools: Review via Konventionen","pt":"Ferramentas de IA: Review-via-Convenções","ru":"ИИ Агенты: Пр