INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('inno-se-toolkit/se-toolkit-lab-4/review-via-conventions', 'review-via-conventions', 'inno-se-toolkit', 'se-toolkit-lab-4', 'community', 'review-via-conventions inno-se-toolkit se-toolkit-lab-4 community review-via-conventions技能用于Lab 04的测试、前端和AI工具开发，实现高效的代码审查 review-via-conventionsスキルは、Lab 04のテスト、フロントエンド、AIエージェント開発で使用され、効率的なコードレビューを実現します review-via-conventions 스킬은 Lab 04의 테스트, 프론트엔드, AI 에이전트 개발에서 사용되어 효율적인 코드 리뷰를 구현합니다 La revisión mediante convenciones es una habilidad de los agentes de AI que permite mejorar la calidad del código y la eficiencia del desarrollo La revue via conventions est une compétence des agents d''IA qui permet d''améliorer la qualité du code et l''efficacité du développement Die Review via Konventionen ist eine Fähigkeit der KI-Tools, die die Code-Qualität und die Entwicklungs-Effizienz verbessert A habilidade de review-via-convenções permite testar e validar a integração de front-end e agentes de IA de forma eficiente Навык проверки через конвенции позволяет тестировать и проверять интеграцию фронтенда и ИИ Агентов эффективно تمكنك مهارة المراجعة من خلال الاتفاقيات من اختبار وتحقق دمج الواجهة الأمامية وأدوات الذكاء الاصطناعي بفعالية Lab 04 — Testing, Front-end, and AI Agents 如何使用review-via-conventions 什么是AI工具 review-via-conventions替代品 review-via-conventions vs 其他工具 review-via-conventions安装 review-via-conventions设置指南 AI工具开发 Lab 04开发 Lab 04 — Testing, Front-end, and AI Agents');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lobehub/lobehub/hotkey', 'community', 'lobehub', 'lobehub', 'lobehub/lobehub', 'hotkey', 0, 0, 36, '2026-03-03T13:05:37.013Z', '2026-03-03T13:43:57.181Z', '06629806123ba243a0222e25e96ab402889832694e529498aee4543f613778bd', '{"id":"lobehub/lobehub/hotkey","name":"hotkey","description":{"zh":"Hotkey 是一个用于查找、构建和协作的 AI智能工具，支持多智能体协作和设计。它提供了一种新的工作和生活方式","ja":"Hotkeyは、AIエージェントの検索、構築、コラボレーションをサポートするプラットフォームです。新しいワークスタイルを提供します","ko":"Hotkey는 검색, 구축 및 협력을 위한 AI 에이전트 플랫폼입니다. 새로운 작업 방식을 제공합니다","es":"hotkey es el espacio perfecto para encontrar, construir y colaborar con agentes que crecen contigo, mejorando la colaboración y el diseño de equipos de agentes.","fr":"hotkey est l''espace idéal pour trouver, construire et collaborer avec des agents qui grandissent avec vous, améliorant la collaboration et la conception d''équipes d''agents.","de":"hotkey ist der perfekte Raum, um Agenten zu finden, zu bauen und mit ihnen zusammenzuarbeiten, die mit Ihnen wachsen, und dabei die Zusammenarbeit und das Design von Agententeams zu verbessern.","pt":"O hotkey é uma plataforma de colaboração de agentes de IA que permite encontrar, construir e trabalhar em equipe com agentes que crescem com você","ru":"hotkey - это платформа для сотрудничества ИИ Агентов, которая позволяет найти, создать и работать в команде с агентами, которые растут с вами","ar":"hotkey هو منصة للتعاون بين وكلاء الذكاء الاصطناعي التي تمكنك من العثور على وكلاء، بناءهم والعمل معهم كفريق","en":"The ultimate space for work and life — to find, build, and collaborate with agent teammates that grow with you. We are taking agent harness to the next level — enabling multi-agent collaboration, effortless agent team design, and introducing agents as the unit of work interaction."},"seo":{"title":{"zh":"AI智能工具 Hotkey","ja":"AIエージェント Hotkey","ko":"AI 에이전트 Hotkey","es":"Herr