INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dkyazzentwatwa/SuperNavigator/nav-stats', 'nav-stats', 'dkyazzentwatwa', 'SuperNavigator', 'community', 'nav-stats dkyazzentwatwa SuperNavigator community nav-stats AI智能代理提供强大的Navigator集成，增强开发效率 nav-stats AIエージェントはNavigatorと統合し、開発効率を向上させる nav-stats AI 에이전트는 Navigator와 통합하여 개발 효율성을 높입니다 La habilidad nav-stats combina superpotencias con un navegador para Claude Code, permitiendo una experiencia de desarrollo única La compétence nav-stats combine des superpouvoirs avec un navigateur pour Claude Code, offrant une expérience de développement unique Die Fähigkeit nav-stats kombiniert Superkräfte mit einem Navigator für Claude Code, ermöglicht eine einzigartige Entwicklungserfahrung Nav-Stats é uma ferramenta de IA que combina superpoderes com navegação para Claude Code, oferecendo uma experiência de desenvolvimento inovadora Nav-Stats - это инструмент ИИ, который сочетает суперспособности с навигацией для Claude Code, предлагая инновационный опыт разработки Nav-Stats هي أداة ذكاء اصطناعي تت结合 القدرات الفائقة مع التصفح ل Claude Code، وتقدم تجربة تطوير مبتكرة Superpowers + Navigator For Claude Code = 🤯 nav-stats安装 AI智能代理是什么 如何使用nav-stats nav-stats和Claude Code nav-stats替代品 nav-stats教程 AI工具nav-stats nav-stats设置指南 Superpowers + Navigator For Claude Code = 🤯');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('getsentry/sentry-javascript/upgrade-otel', 'community', 'getsentry', 'sentry-javascript', 'getsentry/sentry-javascript', 'upgrade-otel', 8596, 1754, 35, '2026-02-28T01:25:16Z', '2026-03-01T05:16:09.644Z', 'e0d1bfbd5f40ba422b929d5364307fb66a9785aad5e953f5642f561c3e904f1e', '{"id":"getsentry/sentry-javascript/upgrade-otel","name":"upgrade-otel","description":{"zh":"升级您的JavaScript应用程序以使用Sentry的官方SDK，实现错误监控和崩溃报告","ja":"Sentryの公式SDKを使用してJavaScriptアプリケーションをアップグレードし、エラーモニタリングとクラッシュレポートを実現する","ko":"Sentry의 공식 SDK를 사용하여 JavaScript 애플리케이션을 업그레이드하여 오류 모니터링 및 크래시 보고 기능을 제공합니다","es":"El SDK de Sentry para JavaScript es una herramienta oficial para la monitorización de errores y la informática de crashed","fr":"Le SDK Sentry pour JavaScript est un outil officiel pour la surveillance des erreurs et l''informatique des crashes","de":"Das offizielle Sentry-SDK für JavaScript ist ein Tool für die Fehlerüberwachung und die Crash-Berichterstellung","pt":"O upgrade-otel é uma ferramenta de IA oficial da Sentry para JavaScript, que melhora a experiência do usuário em aplicações","ru":"Upgrade-otel - официальный инструмент ИИ от Sentry для JavaScript, улучшающий пользовательский опыт в приложениях","ar":"أداة Upgrade-otel هي أداة ذكاء اصطناعي رسمية من Sentry لجافا سكريبت، تحسن تجربة المستخدم في التطبيقات","en":"Official Sentry SDKs for JavaScript"},"seo":{"title":{"zh":"AI智能代理升级-官方Sentry JavaScript SDK","ja":"AIエージェントアップグレード - Sentryの公式JavaScript SDK","ko":"AI 에이전트 업그레이드 - 공식 Sentry JavaScript SDK","es":"Herramientas de upgrade-otel: SDK de Sentry para JavaScript","fr":"Outils upgrade-otel: SDK Sentry pour JavaScript","de":"Upgrade-otel-Tools: Offizielles Sentry-SDK für JavaScript","pt":"Ferramentas de IA: Upgrade-otel para JavaScript","ru":"ИИ Агенты: Upgrade-otel для JavaScript","ar":"أدوات الذكاء الاصطناعي: Upgrade-otel لجافا