INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('getsentry/sentry-javascript/upgrade-otel', 'upgrade-otel', 'getsentry', 'sentry-javascript', 'community', 'upgrade-otel getsentry sentry-javascript community angular crash-reporting ember error-monitoring hacktoberfest javascript javascript-client nextjs node raven react sdk sentry sentry-client tag-production team-sdk-javascript team-web-frontend typescript vue 升级您的JavaScript应用程序以使用Sentry的官方SDK，实现错误监控和崩溃报告 Sentryの公式SDKを使用してJavaScriptアプリケーションをアップグレードし、エラーモニタリングとクラッシュレポートを実現する Sentry의 공식 SDK를 사용하여 JavaScript 애플리케이션을 업그레이드하여 오류 모니터링 및 크래시 보고 기능을 제공합니다 El SDK de Sentry para JavaScript es una herramienta oficial para la monitorización de errores y la informática de crashed Le SDK Sentry pour JavaScript est un outil officiel pour la surveillance des erreurs et l''informatique des crashes Das offizielle Sentry-SDK für JavaScript ist ein Tool für die Fehlerüberwachung und die Crash-Berichterstellung O upgrade-otel é uma ferramenta de IA oficial da Sentry para JavaScript, que melhora a experiência do usuário em aplicações Upgrade-otel - официальный инструмент ИИ от Sentry для JavaScript, улучшающий пользовательский опыт в приложениях أداة Upgrade-otel هي أداة ذكاء اصطناعي رسمية من Sentry لجافا سكريبت، تحسن تجربة المستخدم في التطبيقات Official Sentry SDKs for JavaScript 如何使用Sentry JavaScript错误监控 崩溃报告工具 Sentry SDK Sentry与Bugsnag Sentry安装 Sentry设置指南 Official Sentry SDKs for JavaScript');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('causify-ai/helpers/coding.fix_from_imports', 'community', 'causify-ai', 'helpers', 'causify-ai/helpers', 'coding.fix_from_imports', 141, 128, 35, '2026-02-28T18:01:51Z', '2026-03-01T05:17:06.365Z', '60f90536632903a38bc46ec499b9220a48543a630e281624a358a263f9bdddae', '{"id":"causify-ai/helpers/coding.fix_from_imports","name":"coding.fix_from_imports","description":{"zh":"Coding.fix_from_imports是Causify开发系统的一部分，提供智能的编码修复和优化功能","ja":"Coding.fix_from_importsはCausify開発システムの一部で、スマートなコード修復と最適化機能を提供します","ko":"Coding.fix_from_imports는 Causify 개발 시스템의 일부로智能적인 코드 수정 및 최적화 기능을 제공합니다","es":"Herramienta de IA que analiza y corrige automáticamente las declaraciones de importación ''from ... import'' en código Python. Identifica y soluciona errores de sintaxis comunes, mejorando la legibilidad y el rendimiento del código.","fr":"Outil IA qui analyse et corrige automatiquement les déclarations d''import ''from ... import'' dans le code Python. Identifie et résout les erreurs de syntaxe courantes, améliorant la lisibilité et les performances du code.","de":"KI-Tool, das automatisch ''from ... import''-Anweisungen in Python-Code analysiert und korrigiert. Identifiziert und behebt häufige Syntaxfehler und verbessert die Code-Lesbarkeit und Leistung.","pt":"O coding.fix_from_imports é uma ferramenta de IA que ajuda a melhorar o sistema de desenvolvimento Causify","ru":"ИИ Агент coding.fix_from_imports помогает улучшить систему разработки Causify","ar":"أداة الذكاء الاصطناعي coding.fix_from_imports تساعد على تحسين نظام التطوير Causify","en":"Causify development system"},"seo":{"title":{"zh":"AI智能工具：Coding.fix_from_imports","ja":"AIエージェント：Coding.fix_from_imports","ko":"AI 에이전트: Coding.fix_from_imports","es":"coding.fix_from_imports: Herramienta AI para Python Imports","fr":"coding.fix_from_imports: Outil IA pour les Imports Pytho