INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('theeabrarrr/LPG-Connect/system-reality-auditor', 'system-reality-auditor', 'theeabrarrr', 'LPG-Connect', 'community', 'system-reality-auditor theeabrarrr LPG-Connect community 系统审计员是企业级LPG管理系统，具有多租户、车队跟踪和财务账本功能，使用Next.js和Supabase构建 システムリアリティオーディターは、企業向けのLPG管理システムであり、マルチテナント、車隊追跡、財務台帳機能を備え、Next.jsとSupabaseで構築されています 시스템 리얼리티 감시员은 기업용 LPG 관리 시스템으로, 멀티 테넌트, 차량 추적 및 재무 원장 기능을 갖추고 있으며, Next.js와 Supabase로 구축되었습니다 El sistema de auditoría de realidad de sistema es una herramienta empresarial de gestión de LPG con características de multi-tenencia y seguimiento de flotas L''outil d''audit de réalité système est un outil d''entreprise de gestion LPG avec des fonctionnalités de multi-locataires et de suivi de flotte Das System-Reality-Auditor-Tool ist ein Unternehmens-LPG-Management-System mit Funktionen wie Multi-Tenancy und Flottenverfolgung Sistema de gerenciamento de LPG de nível empresarial com Next.js e Supabase Система управления ЛПГ для предприятий с функциями Next.js и Supabase نظام إدارة الغاز البترولي المسال للشركات مع Next.js و Supabase Enterprise-grade LPG Management System featuring multi-tenancy, fleet tracking, and financial ledgers. Built with Next.js & Supabase. AI智能体 企业级LPG管理系统 Next.js Supabase 多租户 车队跟踪 财务账本 如何使用系统审计员 系统审计员安装指南 Enterprise-grade LPG Management System featuring multi-tenancy, fleet tracking, and financial ledgers. Built with Next.js & Supabase.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sailscastshq/pellicule/pellicule', 'community', 'sailscastshq', 'pellicule', 'sailscastshq/pellicule', 'pellicule', 0, 0, 35, '2026-03-04T13:07:01.663Z', '2026-03-04T13:21:02.585Z', '63fccb591e4b57b034434d674c53ae2cc1bb1ce5afcbfd81aca4fa4d0a19a1fa', '{"id":"sailscastshq/pellicule/pellicule","name":"pellicule","description":{"zh":"Pellicule是一种基于Vue的确定性视频渲染工具，能够帮助开发者创建高质量的视频内容","ja":"Pelliculeは、Vueを使用した決定性ビデオレンダリングツールであり、開発者が高品質のビデオコンテンツを作成するのに役立ちます","ko":"Pellicule은 Vue 기반의 결정적 비디오 렌더링 도구로서 개발자가 고품질의 비디오 콘텐츠를 생성하도록 도와줍니다","es":"Pellicule es una herramienta de renderizado de video determinista para Vue, que permite una renderización precisa y eficiente de videos en aplicaciones web","fr":"Pellicule est un outil de rendering vidéo déterministe pour Vue, qui permet un rendu précis et efficace de vidéos dans les applications web","de":"Pellicule ist ein Tool für deterministische Video-Renderung mit Vue, das eine präzise und effiziente Renderung von Videos in Webanwendungen ermöglicht","pt":"Pellicule é uma ferramenta para renderização de vídeo determinística com Vue, permitindo melhor performance e controle","ru":"Pellicule — это инструмент для детерминированной отрисовки видео с Vue, обеспечивающий лучшую производительность и контроль","ar":"Pellicule هو أداة لتحرير فيديو محدد مع Vue، مما يسمح بالتحكم وال性能 الأفضل","en":"Deterministic video rendering with Vue"},"seo":{"title":{"zh":"Pellicule：基于Vue的确定性视频渲染AI工具","ja":"Pellicule：Vueを使用した決定性ビデオレンダリングAIエージェント","ko":"Pellicule：Vue 기반 결정적 비디오 렌더링 AI 에이전트","es":"Pellicule: Renderizado de video determinista con Vue","fr":"Pellicule: Rendering vidéo déterministe avec Vue","de":"Pellicule: Deterministische Video-Renderung mit Vue","pt":"Pellicule: Renderização de Vídeo Determinística com Vue","ru":"Pellicule: Детерминированная отрисовка видео с Vue","ar":"Pellicule: تحر