INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shinpr/agentic-code/testing', 'testing', 'shinpr', 'agentic-code', 'community', 'testing shinpr agentic-code community AI智能工具提供系统化的测试工作流，帮助开发者提高效率 AIエージェントは、開発者が効率的にテストを行うためのシステム化されたワークフローを提供する AI 에이전트는 개발자가 효율적으로 테스트를 수행할 수 있는 시스템化된 워크플로우를 제공합니다 Los flujos de trabajo sistemáticos para el desarrollo asistido por IA mejoran la calidad y la eficiencia Les flux de travail systématiques pour le développement assisté par IA améliorent la qualité et l''efficacité Systematische Workflows für die AI-gestützte Entwicklung verbessern die Qualität und Effizienz O skill de teste fornece fluxos de trabalho sistemáticos para desenvolvimento assistido por ferramentas de IA, com gateways de qualidade para garantir a entrega de código de alta qualidade Навык тестирования предоставляет системные рабочие процессы для разработки с помощью ИИ Агентов, с контролями качества для обеспечения поставки высококачественного кода مهارة الاختبار توفر تدفقات عمل منهجية لتطوير مدعوم من أدوات الذكاء الاصطناعي، مع بوابات جودة لضمان تسليم كود عالي الجودة Systematic workflows for AI-assisted development - Task-oriented framework with quality gates AI智能工具测试 如何使用AI工具进行测试 AI测试工作流 AI工具与传统测试方法的比较 AI测试安装指南 AI工具测试设置教程 Systematic workflows for AI-assisted development - Task-oriented framework with quality gates');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sushichan044/dotfiles/prepare-issue-pr', 'community', 'sushichan044', 'dotfiles', 'sushichan044/dotfiles', 'prepare-issue-pr', 15, 0, 34, '2026-02-27T09:00:09Z', '2026-02-27T13:10:59.377Z', 'cd2121072b718c922a70b623c02cb3685d7aff29738fbc6050b1b5f162eeb0b1', '{"id":"sushichan044/dotfiles/prepare-issue-pr","name":"prepare-issue-pr","description":{"zh":"prepare-issue-pr AI工具帮助开发者简化代码管理，提高开发效率。我的dotfiles!","ja":"prepare-issue-pr AIエージェントは、開発者がコード管理を簡素化し、開発効率を向上させることを支援します。my dotfiles!","ko":"prepare-issue-pr AI 에이전트는 개발자가 코드 관리를 간소화하고 개발 효율을 향상시키는 것을 지원합니다. my dotfiles!","es":"Prepare-issue-pr es una herramienta de AI que te ayuda a gestionar problemas de forma eficiente, con dotfiles personalizados","fr":"Prepare-issue-pr est un outil d''IA qui vous aide à gérer les problèmes de manière efficace, avec des dotfiles personnalisés","de":"Prepare-issue-pr ist ein KI-Tool, das Ihnen hilft, Probleme effizient zu verwalten, mit benutzerdefinierten Dotfiles","pt":"O prepare-issue-pr é uma ferramenta de AI que ajuda a criar issues e PRs para projetos de desenvolvimento, incluindo a configuração de dotfiles","ru":"ИИ Агент prepare-issue-pr помогает создавать issues и PR для проектов разработки, включая настройку dotfiles","ar":"أداة الذكاء الاصطناعي prepare-issue-pr تساعد في إنشاء المشكلات والطلبات السحب لمشاريع التطوير، بما في ذلك إعداد dotfiles","en":"my dotfiles!"},"seo":{"title":{"zh":"AI工具：prepare-issue-pr","ja":"AIエージェント：prepare-issue-pr","ko":"AI 에이전트: prepare-issue-pr","es":"Herramientas de AI: Prepara problemas con prepare-issue-pr","fr":"Outils d''IA: Préparez les problèmes avec prepare-issue-pr","de":"KI-Tools: Probleme mit prepare-issue-pr vorbereiten","pt":"Ferramentas de AI: prepare-issue-pr para Desenvolvedores","ru":"ИИ Агенты: prepare-issue-pr для Разработчиков","ar":"أدوات الذكاء الاصطناعي: prepare-issue-pr لل مطورين","en":"prepare-issue-pr"},"description":{"zh":"prepare-issue-pr AI工具帮助开发者简化代码管理，提高开发效率。我的dotfiles!","ja":"prepare-issue-pr AIエージェントは、開発者がコード管理を簡素化し、開発効率を向上させることを支援します。my dotfiles!","ko":"prepare-issue-pr AI 에이전트는 개발자가 코드 관리를 간소화하고 개발 효율을 향상시키는 것을 지원합니다. my dotfiles!","es":"Prepare-issue-pr es una herramienta de AI que te ayuda a gestionar problemas de forma eficiente, con dotfiles personalizados","fr":"Prepare-issue-pr est un outil d''IA qui vous aide à gérer les problèmes de manière efficace, avec des dotfiles personnalisés","de":"Prepare-issue-pr ist ein KI-Tool, das Ihnen hilft, Probleme effizient zu verwalten, mit benutzerdefinierten Dotfiles","pt":"O prepare-issue-pr é uma ferramenta de AI que ajuda a criar issues e PRs para projetos de desenvolvimento, incluindo a configuração de dotfiles","ru":"ИИ Агент prepare-issue-pr помогает создавать issues и PR для проектов разработки, включая настройку dotfiles","ar":"أداة الذكاء الاصطناعي prepare-issue-pr تساعد في إنشاء المشكلات والطلبات السحب لمشاريع التطوير، بما في ذلك إعداد dotfiles","en":"my dotfiles!"},"definition":{"en":"my dotfiles!"},"features":{"zh":["简化代码管理","提高开发效率","支持多种代码库","集成CLI工具","支持React和Node.js"],"ja":["コード管理の簡素化","開発効率の向上","複数のコードライブラリのサポート","CLIツールの統合","ReactとNode.jsのサポート"],"ko":["코드 관리를 간소화","개발 효율을 향상","다중 코드 라이브러리의 지원","CLI 도구의 통합","React와 Node.js의 지원"],"es":["Automatización de la preparación de problemas","Dotfiles personalizados","Integración con herramientas de desarrollo","Gestión eficiente de problemas","Compatibilidad con múltiples plataformas"],"fr":["Automatisation de la préparation des problèmes","Dotfiles personnalisés","Intégration avec des outils de développement","Gestion efficace des problèmes","Compatibilité avec plusieurs plateformes"],"de":["Automatisierung der Problemvorbereitung","Benutzerdefinierte Dotfiles","Integration mit Entwicklungstools","Effiziente Problemmangement","Kompatibilität mit mehreren Plattformen"],"pt":["Criação automática de issues e PRs","Configuração de dotfiles","Integração com ferramentas de desenvolvimento","Suporte a múltiplos projetos","Personalização de workflows"],"ru":["Автоматическое создание issues и PR","Настройка dotfiles","Интеграция с инструментами разработки","Поддержка нескольких проектов","Настройка рабочих процессов"],"ar":["إنشاء تلقائي للمشكلات والطلبات السحب","إعداد dotfiles","التكامل مع أدوات التطوير","دعم مشاريع متعددة","تخصيص سير العمل"]},"keywords":{"zh":["如何使用prepare-issue-pr","什么是代码管理工具","prepare-issue-pr替代品","prepare-issue-pr vs git","prepare-issue-pr安装","prepare-issue-pr设置指南","代码管理工具比较"],"ja":["prepare-issue-prの使い方","コード管理ツールとは","prepare-issue-prの代替","prepare-issue-pr vs git","prepare-issue-prのインストール","prepare-issue-prの設定ガイド","コード管理ツールの比較"],"ko":["prepare-issue-pr 사용 방법","코드 관리 도구란","prepare-issue-pr 대체","prepare-issue-pr vs git","prepare-issue-pr 설치","prepare-issue-pr 설정 가이드","코드 관리 도구 비교"],"es":["herramientas de AI para desarrolladores","prepare-issue-pr tutorial","dotfiles personalizados","gestión de problemas eficiente","alternativas a prepare-issue-pr","prepare-issue-pr vs otras herramientas","instalación de prepare-issue-pr","guía de configuración de prepare-issue-pr"],"fr":["outils d''IA pour développeurs","tutoriel prepare-issue-pr","dotfiles personnalisés","gestion de problèmes efficace","alternatives à prepare-issue-pr","prepare-issue-pr vs d''autres outils","installation de prepare-issue-pr","guide de configuration de prepare-issue-pr"],"de":["KI-Tools für Entwickler","prepare-issue-pr-Tutorial","benutzerdefinierte Dotfiles","effizientes Problemmangement","Alternativen zu prepare-issue-pr","prepare-issue-pr im Vergleich zu anderen Tools","Installation von prepare-issue-pr","Konfigurationsanleitung für prepare-issue-pr"],"pt":["como usar prepare-issue-pr","o que é prepare-issue-pr","prepare-issue-pr vs git","prepare-issue-pr instalação","guia de configuração do prepare-issue-pr","ferramentas de ai para desenvolvedores","prepare-issue-pr alternative","prepare-issue-pr tutorial"],"ru":["как использовать prepare-issue-pr","что такое prepare-issue-pr","prepare-issue-pr vs git","установка prepare-issue-pr","руководство по настройке prepare-issue-pr","инструменты ИИ для разработчиков","prepare-issue-pr альтернатива","prepare-issue-pr урок"],"ar":["كيفية استخدام prepare-issue-pr","ما هو prepare-issue-pr","prepare-issue-pr مقابل git","تثبيت prepare-issue-pr","دليل إعداد prepare-issue-pr","أدوات الذكاء الاصطناعي لمطورين","prepare-issue-pr بديل","prepare-issue-pr دروس"]}},"owner":"sushichan044","repo":"dotfiles","repoPath":"sushichan044/dotfiles","stars":15,"forks":0,"updatedAt":"2026-02-27T09:00:09Z","topics":[],"category":"community","skillMd":{"name":"prepare-issue-pr","description":"Prepare comprehensive Issue or Pull Request descriptions using repository templates. Automatically detects type, finds appropriate templates, and guides users through filling them out completely. Use when users want to create Issues or PRs.","bodyPreview":"You are an Issue/PR Preparation Specialist, an expert in creating comprehensive and well-structured Issue and Pull Request descriptions that strictly adhere to repository templates and best practices.\n\nYour primary responsibilities:\n\n1. **Type Detection**: Automatically determine whether to prepare an Issue or Pull Request based on context:\n   - **Issue indicators**: \"issue\", \"イシュー\", \"報告\", \"提案\", \"feature request\", \"bug report\", \"問題\", etc.\n   - **PR indicators**: \"PR\", \"pull request\", \"プルリク\", \"マー","body":"You are an Issue/PR Preparation Specialist, an expert in creating comprehensive and well-structured Issue and Pull Request descriptions that strictly adhere to repository templates and best practices.\n\nYour primary responsibilities:\n\n1. **Type Detection**: Automatically determine whether to prepare an Issue or Pull Request based on context:\n   - **Issue indicators**: \"issue\", \"イシュー\", \"報告\", \"提案\", \"feature request\", \"bug report\", \"問題\", etc.\n   - **PR indicators**: \"PR\", \"pull request\", \"プルリク\", \"マージ\", \"review\", \"レビュー\", \"実装した\", \"finished implementing\", etc.\n   - If unclear from context, ask the user which type they need\n   - Consider git status: if there are uncommitted changes or commits to push, likely a PR; otherwise, likely an Issue\n\n2. **Template Discovery**: Search for templates based on the detected type:\n   - **For Pull Requests**: `fd -H -e md --ignore-case -p ''pull_request_template''`\n   - **For Issues**: `fd -H -e md --ignore-case -p ''issue_template''`\n   - Combine results from both Issue search methods\n\n3. **Template Selection Process**:\n   - If multiple templates are found, present them to the user with clear descriptions and let them choose\n   - If only one template is found, proceed automatically with that template\n   - If no templates are found, inform the user and offer to create a basic PR structure\n\n4. **Template Adherence (CRITICAL)**:\n   - Read the selected template completely and understand every section and requirement\n   - NEVER delete or modify any existing content in the template\n   - Fill out every section that the template requires\n   - Preserve all formatting, checkboxes, and structural elements exactly as they appear\n   - If a section is optional or not applicable, clearly mark it as such rather than removing it\n\n5. **Content Generation**:\n   - **For Pull Requests**:\n     - Use `git --no-pager diff-ancestor-commit` to analyze the changes being made\n     - Include both \"What\" (problem solved, feature added) and implementation details\n     - Reference specific code changes, files modified, and technical decisions\n   - **For Issues**:\n     - DO NOT use git diff commands\n     - Focus on \"What\" (problem statement, desired outcome) and \"Why\" (motivation, impact)\n     - Emphasize user-facing needs, business value, and problem context\n     - Avoid implementation details - that belongs in the PR\n   - **For Both**:\n     - Detect the primary language of the template and write in that language (default to English if unclear)\n     - Provide comprehensive answers to all template questions\n\n6. **Title Generation**:\n   - **For Pull Requests**:\n     - Create a clear, concise title that describes WHAT the PR accomplishes\n     - Focus on the problem solved or feature added, not HOW it was implemented\n     - Follow conventional commit format if the repository uses it\n   - **For Issues**:\n     - Create a clear title that describes the problem or desired feature\n     - Focus on user-facing impact and business value\n     - Use action-oriented language (e.g., \"Add\", \"Fix\", \"Support\", \"Improve\")\n   - **For Both**:\n     - Provide 2-3 title options for the user to choose from\n\n7. **Quality Assurance**:\n   - Ensure all required sections are completed\n   - Verify that the description clearly explains the purpose and impact of changes\n   - Check that any checklists in the template are properly addressed\n   - Confirm that the language and tone match the template''s style\n\n**Workflow**:\n\n1. Detect whether preparing an Issue or Pull Request from context\n2. Search for appropriate templates using the specified fd commands\n3. Present options to user if multiple templates exist\n4. Analyze the selected template thoroughly\n5. Gather information:\n   - **For PR**: Use git commands to analyze changes\n   - **For Issue**: Focus on problem understanding and user needs\n6. Fill out the template completely without removing any existing content\n7. Generate appropriate title suggestions (2-3 options)\n8. Present the completed description and title options to the user\n9. Save the results to a gitignored memo file using the memo command for future reference\n\n**Important Notes**:\n\n- Always preserve the original template structure and content\n- Be thorough in filling out all sections - incomplete templates are not acceptable\n- When in doubt about language, default to English\n- **For PRs**: Focus on both problem resolution and implementation approach; use git commands\n- **For Issues**: Focus on problem statement, motivation, and desired outcomes; avoid implementation details\n- Title should clearly communicate value to readers unfamiliar with the context\n\n**Final Output Process**:\n\nAfter completing the Issue/PR description and title generation:\n\n1. Create a memo file using:\n   - **For PR**: `sidetable memo draft-pr`\n   - **For Issue**: `sidetable memo draft-issue`\n   - Note: This command creates the file to write the results to\n\n2. Write the results to the memo file in the appropriate format:\n\n**For Pull Requests**:\n\n```markdown\n# PR Generation Complete\n\n## PR Title Candidates\n\n1. [Option 1]\n2. [Option 2]\n3. [Option 3]\n\n## Final PR Description\n\n[Complete PR description with all template sections filled]\n\n## Analysis Summary\n\n- Primary changes: [brief summary]\n- Files modified: [count and key files]\n- Impact area: [affected components/features]\n```\n\n**For Issues**:\n\n```markdown\n# Issue Generation Complete\n\n## Issue Title Candidates\n\n1. [Option 1]\n2. [Option 2]\n3. [Option 3]\n\n## Final Issue Description\n\n[Complete Issue description with all template sections filled]\n\n## Problem Summary\n\n- Problem statement: [brief summary]\n- Motivation: [why this matters]\n- Expected impact: [who benefits and how]\n```\n"},"lastSynced":"2026-02-27T13:10:59.377Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents requiring automated Issue and Pull Request preparation with adherence to repository templates and best practices.","zh":"适合需要自动化问题和拉取请求准备的开发人员代理，并且需要遵守仓库模板和最佳实践。","ja":"開発者エージェントが自動的に問題とプルリクエストの準備を行う必要がある場合に最適です。リポジトリのテンプレートとベストプラクティスに従う必要があります。","ko":"개발자 에이전트가 자동으로 문제와 풀 리퀘스트를 준비해야 하는 경우에 적합합니다. 또한 리포지토리 템플릿과 최고의 관행을 준수해야 합니다.","es":"Ideal para Agentes de Desarrollador que requieren preparación automatizada de Problemas y Solicitudes de Extracción con adherencia a plantillas de repositorio y mejores prácticas.","fr":"Idéal pour les Agents de Développeur nécessitant une préparation automatisée des Problèmes et des Demandes de Pull avec adhérence aux modèles de référentiel et aux meilleures pratiques.","de":"Ideal für Entwickleragenten, die eine automatisierte Erstellung von Problemen und Pull-Anfragen mit Einhaltung von Repository-Vorlagen und Best Practices benötigen.","pt":"Ideal para Agentes de Desenvolvedor que exigem preparação automatizada de Problemas e Pedidos de Pull com aderência a modelos de repositório e melhores práticas.","ru":"Идеально подходит для агентов-разработчиков, требующих автоматизированной подготовки вопросов и запросов на включение в репозиторий с соблюдением шаблонов репозитория и лучших практик.","ar":"مثالي لعميل المطور الذي يتطلب تحضيرًا تلقائيًا للقضايا وطلبات السحب مع الالتزام bằng قوالب المستودع وأفضل الممارسات."},"recommendation":{"en":"Empowers agents to automatically determine whether to prepare an Issue or Pull Request based on context, utilizing type detection with indicators such as ''issue'', ''bug report'', or ''PR'', and generating comprehensive descriptions that strictly adhere to repository templates, supporting protocols like GitHub and Bitbucket.","zh":"赋予代理自动确定是否准备问题或拉取请求的能力，利用上下文和类型检测，例如 ''问题''、''错误报告'' 或 ''PR''，并生成详细描述以严格遵守仓库模板，支持 GitHub 和 Bitbucket 等协议。","ja":"エージェントに自動的に問題またはプルリクエストの準備を行うかどうかを決定する能力を与え、コンテキストと型検出を使用し、''問題''、''バグレポート''、または ''PR'' などの指標に基づいて、リポジトリのテンプレートに厳密に従った包括的な説明を生成し、GitHub や Bitbucket などのプロトコルをサポートします。","ko":"에이전트가 자동으로 문제 또는 풀 리퀘스트를 준비할지 여부를 결정할 수 있는 능력을 부여하고, 문脈 및 유형 검사를 사용하여 ''문제'', ''버그 리포트'' 또는 ''PR''와 같은 지표에 따라 리포지토리 템플릿을 엄격히 준수하는 포괄적인 설명을 생성하며, GitHub 및 Bitbucket과 같은 프로토콜을 지원합니다.","es":"Habilita a los agentes a determinar automáticamente si preparar un Problema o una Solicitud de Pull en función del contexto, utilizando la detección de tipo con indicadores como ''problema'', ''informe de error'' o ''PR'', y generando descripciones detalladas que se adhieren estrictamente a las plantillas del repositorio, admitiendo protocolos como GitHub y Bitbucket.","fr":"Permet aux agents de déterminer automatiquement s''ils doivent préparer un Problème ou une Demande de Pull en fonction du contexte, en utilisant la détection de type avec des indicateurs tels que ''problème'', ''rapport de bogue'' ou ''PR'', et en générant des descriptions complètes qui respectent strictement les modèles de référentiel, en prenant en charge des protocoles tels que GitHub et Bitbucket.","de":"Ermächtigt Agenten, automatisch zu bestimmen, ob ein Problem oder eine Pull-Anfrage vorbereitet werden soll, basierend auf dem Kontext, unter Verwendung von Typenerkennung mit Indikatoren wie ''Problem'', ''Fehlerbericht'' oder ''PR'' und Erstellung umfassender Beschreibungen, die sich strikt an die Repository-Vorlagen halten, und unterstützt Protokolle wie GitHub und Bitbucket.","pt":"Habilita os agentes a determinar automaticamente se devem preparar um Problema ou um Pedido de Pull com base no contexto, utilizando a detecção de tipo com indicadores como ''problema'', ''relatório de bug'' ou ''PR'', e gerando descrições abrangentes que aderem estritamente aos modelos de repositório, suportando protocolos como GitHub e Bitbucket.","ru":"Наделяет агентов возможностью автоматически определять, следует ли подготовить вопрос или запрос на включение в репозиторий, исходя из контекста, используя обнаружение типа с индикаторами, такими как ''вопрос'', ''отчет о баге'' или ''PR'', и генерируя подробные описания, которые строго соответствуют шаблонам репозитория, поддерживая протоколы, такие как GitHub и Bitbucket.","ar":"يمنح الوكيل القدرة على تحديد تلقائي ما إذا كان يجب إعداد مشكلة أو طلب سحب بناءً على السياق، باستخدام اكتشاف النوع مع المؤشرات مثل ''مشكلة'' أو ''تقرير الخطأ'' أو ''PR''، وإنشاء وصف شاملة يلتزم بها صرامة بنماذج المستودع، ودعم بروتوكولات مثل GitHub و Bitbucket."},"useCases":{"en":["Automating Issue creation with detailed descriptions","Generating Pull Requests with adherence to repository guidelines","Streamlining bug report submissions with accurate type detection"],"zh":["自动创建问题并包含详细描述","根据仓库指南生成拉取请求","简化错误报告提交并使用准确的类型检测"],"ja":["問題を作成し詳細な説明を含めるための自動化","リポジトリのガイドラインに従ったプルリクエストの生成","バグレポートの提出を簡素化し、正確な型検出を使用"],"ko":["상세한 설명이 포함된 문제 자동 생성","리포지토리 가이드라인에 따라 풀 리퀘스트 생성","정확한 유형 검사를 사용하여 버그 리포트 제출을 간소화"],"es":["Automatización de la creación de Problemas con descripciones detalladas","Generación de Solicitudes de Pull con adherencia a las pautas del repositorio","Optimización de la presentación de informes de errores con detección de tipo precisa"],"fr":["Automatisation de la création de Problèmes avec des descriptions détaillées","Génération de Demandes de Pull avec adhérence aux directives de référentiel","Optimisation de la soumission de rapports de bogues avec une détection de type précise"],"de":["Automatisierung der Erstellung von Problemen mit detaillierten Beschreibungen","Generierung von Pull-Anfragen mit Einhaltung der Repository-Richtlinien","Optimierung der Fehlerberichtseinreichung mit genauer Typenerkennung"],"pt":["Automatizar a criação de Problemas com descrições detalhadas","Gerar Pedidos de Pull com aderência às diretrizes do repositório","Otimizar a apresentação de relatórios de bugs com detecção precisa de tipo"],"ru":["Автоматизировать создание вопросов с подробными описаниями","Генерировать запросы на включение в репозиторий с соблюдением руководящих принципов репозитория","Оптимизировать представление отчетов об ошибках с точным обнаружением типа"],"ar":["توفير إنشاء مشكلات تلقائي مع وصف مفصل","توليد طلبات سحب مع اتباع إرشادات المستودع","تحسين تقديم تقارير الأخطاء بالاكتشاف الدقيق للنوع"]},"limitations":{"en":["Requires access to repository templates and guidelines","Limited to text-based Issue and Pull Request descriptions"],"zh":["需要访问仓库模板和指南","仅限文本 기반的问题和拉取请求描述"],"ja":["リポジトリのテンプレートとガイドラインへのアクセスが必要","テキストベースの問題とプルリクエストの説明のみ"],"ko":["리포지토리 템플릿 및 가이드라인에 대한 액세스가 필요","텍스트 기반의 문제 및 풀 리퀘스트 설명만"],"es":["Requiere acceso a plantillas y pautas de repositorio","Limitado a descripciones de Problemas y Solicitudes de Pull basadas en texto"],"fr":["Nécessite un accès aux modèles et directives de référentiel","Limité aux descriptions de Problèmes et de Demandes de Pull basées sur le texte"],"de":["Benötigt Zugriff auf Repository-Vorlagen und -Richtlinien","Begrenzt auf textbasierte Problemm- und Pull-Anfragenbeschreibungen"],"pt":["Exige acesso a modelos e diretrizes de repositório","Limitado a descrições de Problemas e Pedidos de Pull baseadas em texto"],"ru":["Требует доступа к шаблонам и руководящим принципам репозитория","Ограничен описаниями вопросов и запросов на включение в репозиторий, основанными на тексте"],"ar":["يتطلب الوصول إلى نماذج وإرشادات المستودع","محدود بوصف المشكلات وطلبات السحب القائمة على النص"]},"version":3},"contentHash":"cd2121072b718c922a70b623c02cb3685d7aff29738fbc6050b1b5f162eeb0b1","qualityScore":34}');
