INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('steinbeck/nmrxiv-downloader/nmrxiv', 'nmrxiv', 'steinbeck', 'nmrxiv-downloader', 'community', 'nmrxiv steinbeck nmrxiv-downloader community nmrxiv下载器是一个Python CLI工具，用于在nmrxiv.org上搜索和下载NMR光谱数据集 nmrxivダウンローダーはnmrxiv.org上的NMRスペクトルデータセットを検索してダウンロードするためのPython CLIツール nmrxiv 다운로드기는 nmrxiv.org上的 NMR 분광 데이터셋을 검색 및 다운로드하기 위한 Python CLI 도구 nmrxiv es una herramienta de línea de comandos de Python para buscar y descargar conjuntos de datos NMR de nmrxiv.org. Ofrece funcionalidades para listar proyectos y conjuntos de datos, buscar moléculas y más nmrxiv est un outil de ligne de commande Python pour rechercher et télécharger des jeux de données NMR à partir de nmrxiv.org. Il propose des fonctionnalités pour lister les projets et les jeux de données, rechercher des molécules et plus encore nmrxiv ist ein Python-CLI-Tool zum Suchen und Herunterladen von NMR-Datensätzen von nmrxiv.org. Es bietet Funktionen zum Auflisten von Projekten und Datensätzen, zur Suche nach Molekülen und mehr A ferramenta nmrxiv é uma CLI Python para busca e download de conjuntos de dados de NMR de nmrxiv.org. Ela permite listar projetos e conjuntos de dados, buscar moléculas e mais. Инструмент nmrxiv - это CLI на Python для поиска и скачивания наборов данных ЯМР с nmrxiv.org. Он позволяет листать проекты и наборы данных, искать молекулы и многое другое. أداة nmrxiv هي سطر أوامر بايثون للبحث وتنزيل مجموعات بيانات الرنين المغناطيسي النووي من nmrxiv.org. يمكنها قائمة المشاريع ومجموعات البيانات، البحث عن الجزيئات والمزيد Python CLI for Claude Code to search and download NMR datasets from nmrxiv.org NMR数据集 nmrxiv下载器 Python CLI 数据集搜索 数据下载 NMR光谱 Python CLI for Claude Code to search and download NMR datasets from nmrxiv.org');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cloudflare/moltworker/cloudflare-browser', 'community', 'cloudflare', 'moltworker', 'cloudflare/moltworker', 'cloudflare-browser', 0, 0, 34, '2026-03-04T13:07:01.666Z', '2026-03-04T13:21:56.047Z', '06f8f67410955ff10065b70d306e1c996a3cd12e429346099d495dfacec1f483', '{"id":"cloudflare/moltworker/cloudflare-browser","name":"cloudflare-browser","description":{"zh":"Cloudflare 浏览器渲染控制允许您使用 Chrome DevTools Protocol 进行浏览器渲染控制","ja":"Cloudflare ブラウザレンダリング制御は、Chrome DevTools Protocol を使用したブラウザレンダリング制御を可能にします","ko":"클라우드플레어 브라우저 렌더링 제어는 크롬 개발자 도구 프로토콜을 사용한 브라우저 렌더링 제어를 허용합니다","es":"El servicio de renderizado de Cloudflare permite controlar navegadores headless mediante CDP. Configure su entorno con OpenClaw y Cloudflare Workers.","fr":"Le service de rendu de Cloudflare permet de contrôler les navigateurs headless via CDP. Configurez votre environnement avec OpenClaw et Cloudflare Workers.","de":"Der Cloudflare-Renderdienst ermöglicht die Steuerung von headless-Browsern über CDP. Konfigurieren Sie Ihre Umgebung mit OpenClaw und Cloudflare Workers.","pt":"O Cloudflare Browser Rendering permite controlar navegadores headless via CDP e WebSocket. Configure seu ambiente com OpenClaw e Cloudflare Workers","ru":"Сервис рендеринга браузера Cloudflare позволяет контролировать безголовые браузеры через CDP и WebSocket. Настройте свою среду с OpenClaw и Cloudflare Workers","ar":"خدمة عرض المتصفح من Cloudflare تسمح بالتحكم في المتصفحات بدون رأس عبر CDP و WebSocket. قم بتكوين بيئتك مع OpenClaw و Cloudflare Workers","en":"Run OpenClaw, (formerly Moltbot, formerly Clawdbot) on Cloudflare Workers"},"seo":{"title":{"zh":"Cloudflare 浏览器渲染控制","ja":"Cloudflare ブラウザレンダリング制御","ko":"클라우드플레어 브라우저 렌더링 제어","es":"Control de navegador en Cloudflare","fr":"Contrôle du navigateur sur Cloudflare","de":"Cloudflare Browser-Steuerung","pt":"Controle