INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('elbwalker/walkerOS/walkeros-understanding-flow', 'walkeros-understanding-flow', 'elbwalker', 'walkerOS', 'community', 'walkeros-understanding-flow elbwalker walkerOS community Walkeros理解流程是开发人员的开源标签管理器，用于简化标签管理和优化工作流程 Walkeros Understanding Flowは開発者のためのオープンソースタグマネージャーです Walkeros 이해 흐름은 개발자를 위한 오픈소스 태그 매니저로 태그 관리와 워크플로우 최적화를 지원합니다 walkeros-understanding-flow es un administrador de etiquetas de código abierto para desarrolladores que simplifica el flujo de trabajo walkeros-understanding-flow est un gestionnaire de balises open-source pour les développeurs qui simplifie le flux de travail walkeros-understanding-flow ist ein Open-Source-Tag-Manager für Entwickler, der den Arbeitsfluss vereinfacht O walkeros-understanding-flow é um gerenciador de tags de código aberto para desenvolvedores, permitindo uma maior flexibilidade e controle Walkeros-understanding-flow - открытый тег-менеджер для разработчиков, обеспечивающий большую гибкость и контроль walkeros-understanding-flow هو مدير علامات مفتوح المصدر لل مطورين، مما يسمح بمرونة وقوة التحكم أكبر Open-source tag manager for developers Walkeros理解流程 开源标签管理器 如何使用Walkeros 什么是标签管理 Walkeros替代品 Walkeros与Google Tag Manager比较 Walkeros安装 Walkeros设置指南 Open-source tag manager for developers');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Yeachan-Heo/oh-my-claudecode/ultrawork', 'community', 'Yeachan-Heo', 'oh-my-claudecode', 'Yeachan-Heo/oh-my-claudecode', 'ultrawork', 0, 0, 34, '2026-03-04T13:07:01.672Z', '2026-03-04T13:23:01.826Z', 'a5ca384b8ae5e556296420adb712e41cc6ab2e49088960469d874b587634550e', '{"id":"Yeachan-Heo/oh-my-claudecode/ultrawork","name":"ultrawork","description":{"zh":"Ultrawork是一种团队优先的多智能体编排工具，用于简化Claude Code开发。它通过自动化工作流程和任务管理来提高开发效率","ja":"Ultraworkは、Claude Code開発を簡素化するためのチームファーストなマルチエージェントオーケストレーションツールです。ワークフローとタスク管理の自動化により開発効率を向上させます","ko":"Ultrawork는 Claude Code 개발을 간소화하는 팀 우선의 멀티 에이전트 오케스트레이션 도구입니다. 작업 흐름과 작업 관리의 자동화를 통해 개발 효율성을 향상시킵니다","es":"ultrawork es una herramienta de orquestación de agentes para Claude Code que mejora la colaboración en equipo. Con ultrawork, los desarrolladores pueden trabajar de manera más eficiente","fr":"ultrawork est un outil d''orchestration multi-agents pour Claude Code qui améliore la collaboration d''équipe. Avec ultrawork, les développeurs peuvent travailler de manière plus efficace","de":"ultrawork ist ein Tool für die Orchestrierung von Multi-Agenten für Claude Code, das die Teamzusammenarbeit verbessert. Mit ultrawork können Entwickler effizienter arbeiten","pt":"O Ultrawork é uma solução de orquestração de agentes de IA para Claude Code, projetada para equipes. Ele permite a integração e gerenciamento de agentes de IA para melhorar a produtividade","ru":"Ultrawork - решение для мультиагентной оркестрации для Claude Code, предназначенное для команд. Оно позволяет интегрировать и управлять ИИ Агентами для повышения производительности","ar":"ألتروورك هو حل لإدارة الوحدات المتعددة لآي كلود كود، مصمم للفرق. يسمح بدمج وإدارة وحدات آي كي لتحسين الإنتاجية","en":"Teams-first Multi-agent orchestration for Claude Code"},"seo":{"title":{"zh":"Ultrawork AI智能代理 - Claude Code团队优先的多智能体编排","ja":