INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nathanvale/vtm-cli/git-expert', 'git-expert', 'nathanvale', 'vtm-cli', 'community', 'git-expert nathanvale vtm-cli community git-expert是令开发更高效的AI辅助开发工具，通过Claude Code实现Token-efficient任务管理 git-expertは開発の生産性を向上させるAIエージェントです。Claude Codeを使用したToken-efficientタスク管理を実現します git-expert는 개발 생산성을 향상시키는 AI 에이전트로 Claude Code를 사용하여 Token-efficient 작업 관리를 제공합니다 Claude Code es una herramienta de gestión de tareas token-efficient para desarrollo asistido por IA Claude Code est un outil de gestion de tâches token-efficient pour le développement assisté par l''IA Claude Code ist ein token-efficientes Task-Management-Tool für die KI-gestützte Entwicklung O especialista em git é uma ferramenta de IA para gerenciamento de tarefas, ajudando desenvolvedores a trabalhar de forma mais eficiente com Claude Code Эксперт Git - это инструмент ИИ для управления задачами, помогающий разработчикам работать более эффективно с Claude Code خبير جيت هو أداة ذكاء اصطناعي لإدارة المهام، مما يساعد المطورين على العمل بطريقة أكثر فعالية مع Claude Code Token-efficient task management for AI-assisted development with Claude Code 如何使用git-expert 什么是AI智能工具 git-expert替代品 git-expert vs 其他工具 git-expert安装 git-expert设置指南 AI辅助开发工具 Token-efficient任务管理 Token-efficient task management for AI-assisted development with Claude Code');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vechain/inspector-app/karpathy-guidelines', 'community', 'vechain', 'inspector-app', 'vechain/inspector-app', 'karpathy-guidelines', 0, 0, 34, '2026-03-04T13:07:01.693Z', '2026-03-04T13:35:09.382Z', 'ada2bbcebc34310151b3ec66d6d2f9368f2a210edf95d60318fcb1fd6bfd9459', '{"id":"vechain/inspector-app/karpathy-guidelines","name":"karpathy-guidelines","description":{"zh":"karpathy-guidelines是智能合约探索工具，允许与VeChain网络上的合约交互","ja":"karpathy-guidelinesはスマートコントラクトエクスプローラーであり、VeChainネットワーク上のコントラクトとインタラクティブにします","ko":"karpathy-guidelines는 스마트 계약 탐색기로서 VeChain 네트워크上的 계약과 상호 작용할 수 있습니다","es":"karpathy-guidelines es una herramienta de exploración de contratos inteligentes que permite interactuar con contratos en redes VeChain","fr":"karpathy-guidelines est un outil d''exploration de contrats intelligents qui permet d''interagir avec les contrats sur les réseaux VeChain","de":"karpathy-guidelines ist ein Smart-Contract-Explorer-Tool, das die Interaktion mit Verträgen in VeChain-Netzwerken ermöglicht","pt":"A ferramenta karpathy-guidelines é um explorador de contratos inteligentes para interagir com contratos na rede VeChain. Fornece funcionalidades para desenvolvedores trabalharem com contratos de forma eficiente","ru":"Инструмент karpathy-guidelines - это инструмент для работы с контрактами в сети VeChain. Он предоставляет разработчикам функции для эффективной работы с контрактами","ar":"أداة karpathy-guidelines هي أداة استكشاف العقود الذكية للتفاعل مع العقود على شبكة في تشين. توفر أداةkarpathy-guidelines ميزات للمانحين للعمل مع العقود بطريقة فعالة","en":"Smart contract explorer tool: interact with contracts on VeChain networks"},"seo":{"title":{"zh":"智能合约工具karpathy-guidelines","ja":"AIエージェント：karpathy-guidelinesスマートコントラクトエクスプローラー","ko":"AI 에이전트: karpathy-guidelines 스마트 계약 탐색기","es":"Herramientas de inteligencia artificial: ka