INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('junerver/ComposeHooks/compose-hooks', 'compose-hooks', 'junerver', 'ComposeHooks', 'community', 'compose-hooks junerver ComposeHooks community Compose Hooks AIエージェント允许您在Compose Multiplatform中使用React风格的Hooks，实现更容易的状态管理 Compose Hooks AIエージェントは、Compose MultiplatformでReactスタイルのHooksを使用できるようにし、状態管理をより簡単にします Compose Hooks AI 에이전트는 Compose Multiplatform에서 React 스타일의 Hooks를 사용할 수 있게 해주어 상태 관리를 더 쉽게 합니다 Compose Hooks es una herramienta de AI que permite usar hooks de React en Compose Multiplatform para una gestión de estado más sencilla Compose Hooks est un outil IA qui permet d''utiliser des hooks React dans Compose Multiplatform pour une gestion d''état plus simple Compose Hooks ist ein KI-Tool, das es ermöglicht, React-Hooks in Compose Multiplatform zu verwenden, um den Zustand einfacher zu verwalten Compose Hooks é uma ferramenta de IA que permite usar hooks de estilo React em Compose Multiplatform para gerenciar estado de forma mais fácil Compose Hooks — это инструмент ИИ, который позволяет использовать хуки в стиле React в Compose Multiplatform для более легкого управления состоянием Compose Hooks هو أداة ذكاء اصطناعي تتيح استخدام Hooks بالشكل التفاعلي في Compose Multiplatform لتسهيل إدارة الحالة use React style hooks in Compose Multiplatform to easier management state 如何使用Compose Hooks 什么是React Hooks Compose Multiplatform教程 Compose Hooks AIエージェント安装 React Hooks与Compose Hooks比较 Compose Hooks使用指南 状态管理最佳实践 Compose Hooks替代品 use React style hooks in Compose Multiplatform to easier management state');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SprocketLab/slop-code-bench/checkpoint-ambiguity-review', 'community', 'SprocketLab', 'slop-code-bench', 'SprocketLab/slop-code-bench', 'checkpoint-ambiguity-review', 0, 0, 34, '2026-03-04T13:07:01.741Z', '2026-03-04T14:06:12.008Z', '9fe11cc04eba1fa7dac9842ba3d40b74cc3986fe396c90aabb89a6f9b416dcf2', '{"id":"SprocketLab/slop-code-bench/checkpoint-ambiguity-review","name":"checkpoint-ambiguity-review","description":{"zh":"SlopCodeBench是一种测量代码腐蚀的工具，Checkpoint Ambiguity Review是其关键功能","ja":"SlopCodeBenchはコードの腐敗を測定するツールであり、Checkpoint Ambiguity Reviewはその重要な機能です","ko":"SlopCodeBench는 코드 부패를 측정하는 도구이며 체크포인트 애매성 검토는 주요 기능입니다","es":"SlopCodeBench es una herramienta de código que mide la erosión del código bajo la refinación iterativa de especificaciones","fr":"SlopCodeBench est un outil de code qui mesure l''érosion du code sous l''affinement itératif des spécifications","de":"SlopCodeBench ist ein Code-Tool, das die Code-Erosion unter iterativer Spezifikationsverfeinerung misst","pt":"SlopCodeBench é uma ferramenta de IA que mede a erosão de código sob refinamento iterativo de especificações","ru":"SlopCodeBench - это инструмент ИИ, который измеряет эрозию кода под итеративным уточнением спецификаций","ar":"SlopCodeBench هي أداة ذكاء اصطناعي تقيس تآكل الكود تحت التنقية المتكررة للمواصفات","en":"SlopCodeBench: Measuring Code Erosion Under Iterative Specification Refinement"},"seo":{"title":{"zh":"AI工具：Checkpoint Ambiguity Review","ja":"AIエージェント：チェックポイントの曖昧さをレビュー","ko":"AI 에이전트: 체크포인트 애매성 검토","es":"Herramientas de IA: Revisión de ambigüedad de puntos de c...","fr":"Outils d''IA : Revue de l''ambiguïté des points de contrôle","de":"KI-Tools: Überprüfung von Checkpoint-Mehrdeutigkeit","pt":"Ferramentas de IA: Revisão de Ambiguidade de Checkpoint","ru":"ИИ Агенты: Проверка Неоднозначности Checkpoint","ar":"أدوات الذكاء ا