INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SprocketLab/slop-code-bench/checkpoint-ambiguity-review', 'checkpoint-ambiguity-review', 'SprocketLab', 'slop-code-bench', 'community', 'checkpoint-ambiguity-review SprocketLab slop-code-bench community SlopCodeBench是一种测量代码腐蚀的工具，Checkpoint Ambiguity Review是其关键功能 SlopCodeBenchはコードの腐敗を測定するツールであり、Checkpoint Ambiguity Reviewはその重要な機能です SlopCodeBench는 코드 부패를 측정하는 도구이며 체크포인트 애매성 검토는 주요 기능입니다 SlopCodeBench es una herramienta de código que mide la erosión del código bajo la refinación iterativa de especificaciones SlopCodeBench est un outil de code qui mesure l''érosion du code sous l''affinement itératif des spécifications SlopCodeBench ist ein Code-Tool, das die Code-Erosion unter iterativer Spezifikationsverfeinerung misst SlopCodeBench é uma ferramenta de IA que mede a erosão de código sob refinamento iterativo de especificações SlopCodeBench - это инструмент ИИ, который измеряет эрозию кода под итеративным уточнением спецификаций SlopCodeBench هي أداة ذكاء اصطناعي تقيس تآكل الكود تحت التنقية المتكررة للمواصفات SlopCodeBench: Measuring Code Erosion Under Iterative Specification Refinement 如何使用Checkpoint Ambiguity Review 什么是SlopCodeBench AI工具Checkpoint Ambiguity Review Checkpoint Ambiguity Review替代品 SlopCodeBench安装 代码腐蚀测量工具 AI驱动的代码优化 Checkpoint Ambiguity Review教程 SlopCodeBench: Measuring Code Erosion Under Iterative Specification Refinement');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sylin-org/koi/explore', 'community', 'sylin-org', 'koi', 'sylin-org/koi', 'explore', 0, 0, 34, '2026-03-04T13:07:01.741Z', '2026-03-04T14:06:15.105Z', '27206e323e2ea1811659ed31a031b634e61f279727f4d7f03bf156542d7dd840', '{"id":"sylin-org/koi/explore","name":"explore","description":{"zh":"探索AIエージェント提供本地mDNS服务发现功能，帮助开发者高效地发现和管理本地服务","ja":"AIエージェントの探索はローカルmDNSサービスの検出機能を提供し、開発者が効率的にローカルサービスを検出して管理できるようにします","ko":"탐색 AI 에이전트는 로컬 mDNS 서비스 발견 기능을 제공하여 개발자가 효율적으로 로컬 서비스를 발견하고 관리할 수 있습니다","es":"Nuestra herramienta de exploración de servicios mDNS locales permite a los desarrolladores descubrir y utilizar servicios de red de forma fácil y eficiente","fr":"Notre outil d''exploration de services mDNS locaux permet aux développeurs de découvrir et d''utiliser des services de réseau de manière facile et efficace","de":"Unser Tool zur lokalen mDNS-Service-Entdeckung ermöglicht es Entwicklern, Netzwerkdienste einfach und effizient zu entdecken und zu nutzen","pt":"A ferramenta explore é um serviço de descoberta mDNS local para todos. Desenvolva aplicações com facilidade utilizando essa tecnologia.","ru":"Инструмент explore - это местная служба обнаружения mDNS для всех. Разрабатывайте приложения легко, используя эту технологию.","ar":"أداة explore هي خدمة اكتشاف مDNS محلية للجميع. قم بتطوير التطبيقات بسهولة باستخدام هذه التكنولوجيا.","en":"Local mDNS service discovery for everyone."},"seo":{"title":{"zh":"探索AIエージェント - 本地mDNS服务发现","ja":"AIエージェントの探索 - ローカルmDNSサービスの検出","ko":"탐색 AI 에이전트 - 로컬 mDNS 서비스 발견","es":"Herramientas de exploración de servicios mDNS locales par...","fr":"Outils d''exploration de services mDNS locaux pour les dév...","de":"Lokale mDNS-Service-Entdeckungstools für Entwickler","pt":"Ferramentas de IA: explore - Serviço de Descoberta mDNS L...","ru":"ИИ Агенты: explore - Местная служба обнаружения mDNS","ar":"أدوات الذكاء الاصطناعي: explore - خدمة اكتشاف مDNS المحلية","en":"explore"},"description":{"zh":"探索AIエージェント提供本地mDNS服务发现功能，帮助开发者高效地发现和管理本地服务","ja":"AIエージェントの探索はローカルmDNSサービスの検出機能を提供し、開発者が効率的にローカルサービスを検出して管理できるようにします","ko":"탐색 AI 에이전트는 로컬 mDNS 서비스 발견 기능을 제공하여 개발자가 효율적으로 로컬 서비스를 발견하고 관리할 수 있습니다","es":"Nuestra herramienta de exploración de servicios mDNS locales permite a los desarrolladores descubrir y utilizar servicios de red de forma fácil y eficiente","fr":"Notre outil d''exploration de services mDNS locaux permet aux développeurs de découvrir et d''utiliser des services de réseau de manière facile et efficace","de":"Unser Tool zur lokalen mDNS-Service-Entdeckung ermöglicht es Entwicklern, Netzwerkdienste einfach und effizient zu entdecken und zu nutzen","pt":"A ferramenta explore é um serviço de descoberta mDNS local para todos. Desenvolva aplicações com facilidade utilizando essa tecnologia.","ru":"Инструмент explore - это местная служба обнаружения mDNS для всех. Разрабатывайте приложения легко, используя эту технологию.","ar":"أداة explore هي خدمة اكتشاف مDNS محلية للجميع. قم بتطوير التطبيقات بسهولة باستخدام هذه التكنولوجيا.","en":"Local mDNS service discovery for everyone."},"definition":{"en":"Local mDNS service discovery for everyone."},"features":{"zh":["本地mDNS服务发现","支持多种开发语言","高效的服务管理","易于使用的CLI接口","与React、Python、Node.js等框架集成"],"ja":["ローカルmDNSサービスの検出","多くの開発言語をサポート","効率的なサービス管理","使いやすいCLIインターフェース","React、Python、Node.jsなどのフレームワークとの統合"],"ko":["로컬 mDNS 서비스 발견","다수의 개발 언어 지원","효율적인 서비스 관리","쉽게 사용할 수 있는 CLI 인터페이스","React, Python, Node.js 등의 프레임워크와의 통합"],"es":["Detección automática de servicios mDNS","Exploración de dispositivos y servicios en la red","Compatibilidad con múltiples plataformas","Integración con herramientas de desarrollo populares","Documentación y soporte técnico"],"fr":["Détection automatique des services mDNS","Exploration des appareils et des services sur le réseau","Compatibilité avec plusieurs plateformes","Intégration avec des outils de développement populaires","Documentation et support technique"],"de":["Automatische Erkennung von mDNS-Diensten","Entdeckung von Geräten und Diensten im Netzwerk","Kompatibilität mit mehreren Plattformen","Integration mit beliebten Entwicklungstools","Dokumentation und technischer Support"],"pt":["Descoberta de serviços mDNS locais","Desenvolvimento de aplicações com facilidade","Integração com tecnologias como React e Node.js","Suporte a CLI","Compatibilidade com diferentes plataformas"],"ru":["Местное обнаружение служб mDNS","Разработка приложений легко","Интеграция с технологиями như React и Node.js","Поддержка CLI","Совместимость с разными платформами"],"ar":["اكتشاف خدمات مDNS المحلية","تطوير التطبيقات بسهولة","التكامل مع تكنولوجيا مثل React و Node.js","دعم CLI","التوافق مع منصات مختلفة"]},"keywords":{"zh":["如何使用探索AIエージェント","什么是mDNS服务发现","探索AIエージェント安装","探索AIエージェント设置指南","探索AIエージェント替代品","探索AIエージェント与其他工具的比较"],"ja":["AIエージェントの探索の使い方","mDNSサービスの検出とは","AIエージェントの探索のインストール","AIエージェントの探索の設定ガイド","AIエージェントの探索の代替品","AIエージェントの探索と他のツールの比較"],"ko":["탐색 AI 에이전트 사용법","mDNS 서비스 발견이란","탐색 AI 에이전트 설치","탐색 AI 에이전트 설정 가이드","탐색 AI 에이전트 대체품","탐색 AI 에이전트와 다른 도구의 비교"],"es":["herramientas de exploración de servicios mDNS","cómo utilizar mDNS","qué es mDNS","alternativas a mDNS","mDNS vs DNS","instalación de mDNS","guía de configuración de mDNS"],"fr":["outils d''exploration de services mDNS","comment utiliser mDNS","quoi est mDNS","alternatives à mDNS","mDNS vs DNS","installation de mDNS","guide de configuration de mDNS"],"de":["Tools zur lokalen mDNS-Service-Entdeckung","wie man mDNS verwendet","was ist mDNS","Alternativen zu mDNS","mDNS vs DNS","Installation von mDNS","Konfigurationsanleitung für mDNS"],"pt":["ferramentas de IA","como usar explore","o que é mDNS","explore vs outras ferramentas","instalar explore","guia de configuração do explore","desenvolvimento de aplicações com explore","explorar serviços locais"],"ru":["ИИ Агенты","как использовать explore","что такое mDNS","explore vs другие инструменты","установить explore","руководство по настройке explore","разработка приложений с explore","обнаружение местных служб"],"ar":["أدوات الذكاء الاصطناعي","كيفية استخدام explore","ما هي مDNS","explore مقابل أدوات أخرى","تثبيت explore","دليل إعداد explore","تطوير التطبيقات مع explore","اكتشاف الخدمات المحلية"]}},"owner":"sylin-org","repo":"koi","repoPath":"sylin-org/koi","stars":0,"forks":0,"updatedAt":"2026-03-04T13:07:01.741Z","topics":[],"category":"community","skillMd":{"name":"explore","description":"Run a mandatory pre-implementation exploration workflow before writing production code. Use when a task requires code changes and Codex must first map concerns/layers, read relevant files, check existing constants and types, identify the closest existing pattern, plan exact code placement, and confirm architectural guardrails.","bodyPreview":"# Explore\n\nBefore implementing anything for a task, complete the following steps in order.\nDo not write production code until all steps are done.\n\n## Step 1: Understand the task\n\nRestate the task in your own words. Identify:\n- What crate this touches: `koi-common`, `koi-client`, `koi-mdns`, `koi-config`, `koi-dns`, `koi-health`, `koi-proxy`, `koi-certmesh`, `koi-crypto`, `koi-truststore`, `koi-embedded`, `koi` binary\n- Which layer is involved: transport, business logic, wire format, CLI\n- Expect","body":"# Explore\n\nBefore implementing anything for a task, complete the following steps in order.\nDo not write production code until all steps are done.\n\n## Step 1: Understand the task\n\nRestate the task in your own words. Identify:\n- What crate this touches: `koi-common`, `koi-client`, `koi-mdns`, `koi-config`, `koi-dns`, `koi-health`, `koi-proxy`, `koi-certmesh`, `koi-crypto`, `koi-truststore`, `koi-embedded`, `koi` binary\n- Which layer is involved: transport, business logic, wire format, CLI\n- Expected output: new feature, refactor, bug fix, extension\n\n## Step 2: Read existing code\n\nOpen and read the 3-5 most relevant existing files.\nUse searches like:\n\n```bash\n# Find types related to the task\nrg \"struct|enum|trait\" crates/ -l | head -20\n\n# Find functions related to the task\nrg \"fn keyword_from_task\" crates/\n\n# Find the closest existing implementation to what we''re building\nrg \"similar_feature_keyword\" crates/ -l\n```\n\nFor each file read, state in one sentence what it does and whether it is relevant.\n\n## Step 3: Check for existing constants and types\n\nRun these searches explicitly and report results:\n\n```bash\n# Constants in the binary crate\nrg \"const \" crates/koi/src/\n\n# Shared types and utilities\nrg \"struct|enum\" crates/koi-common/src/\nrg \"struct|enum\" crates/koi-mdns/src/protocol/\n\n# Client types\nrg \"struct|enum\" crates/koi-client/src/\n\n# Domain crate types\nrg \"struct|enum\" crates/koi-dns/src/\nrg \"struct|enum\" crates/koi-health/src/\nrg \"struct|enum\" crates/koi-proxy/src/\nrg \"struct|enum\" crates/koi-certmesh/src/\n```\n\nFor each required piece of functionality, state clearly:\n- `Already exists`\n- `Needs to be created`\n\n## Step 4: Identify the closest pattern to follow\n\nFind the most similar existing feature in the codebase.\nExamples:\n- New HTTP endpoint: read `crates/koi/src/adapters/http.rs` or `crates/koi/src/adapters/dispatch.rs`\n- New CLI command: read a module in `crates/koi/src/commands/`\n- New shared types: read `crates/koi-common/src/types.rs` or `crates/koi-common/src/api.rs`\n- New domain logic: read the relevant domain crate (e.g., `crates/koi-mdns/`, `crates/koi-dns/`)\n- Platform integration: read `crates/koi/src/platform/`\n- Formatting: read `crates/koi/src/format.rs`\n- Client operations: read `crates/koi-client/src/lib.rs`\n\nState:\n- `Following the pattern from [specific file]`\n\n## Step 5: Plan where new code will live\n\nFor every new file, type, function, or constant, state location and justification:\n\n| New code | Location | Justification |\n|----------|----------|---------------|\n| (type/fn/const) | (exact path) | (why here and not elsewhere) |\n\nApply crate placement rules:\n- Shared types, traits, utilities: `crates/koi-common/`\n- mDNS protocol types: `crates/koi-mdns/`\n- HTTP client methods: `crates/koi-client/`\n- CLI commands / subcommands: `crates/koi/src/commands/`\n- HTTP server / adapters: `crates/koi/src/adapters/`\n- OS integration: `crates/koi/src/platform/`\n- Output formatting: `crates/koi/src/format.rs`\n- DNS domain logic: `crates/koi-dns/`\n- Health checks: `crates/koi-health/`\n- Reverse proxy: `crates/koi-proxy/`\n- Certificate mesh: `crates/koi-certmesh/`\n- Crypto primitives: `crates/koi-crypto/`\n- Configuration / breadcrumb: `crates/koi-config/`\n\n## Step 6: Check for potential violations\n\nBefore proceeding, confirm:\n\n- [ ] No `mdns-sd` imports outside `crates/koi-mdns/`\n- [ ] No new type duplicates one in `koi-common` or domain crates\n- [ ] Constants are co-located with usage (not in a centralized module)\n- [ ] New protocol types have serde round-trip tests planned\n- [ ] Cross-crate dependencies flow downward (binary -> domain crates -> koi-common)\n\n## Step 7: Present the plan\n\nSummarize findings in this exact format:\n\n**Task:** (one sentence)\n**Files read:** (list with one-sentence relevance notes)\n**Reusing:** (list what already exists)\n**Creating new:** (table from Step 5)\n**Pattern:** (which existing file you''re following)\n**Risks:** (anything you''re unsure about)\n\nThen stop and wait for approval before implementing.\n"},"lastSynced":"2026-03-04T14:06:15.105Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing structured task analysis and local mDNS service discovery capabilities.","zh":"非常适合需要结构化任务分析和本地mDNS服务发现能力的开发代理。","ja":"開発エージェントが構造化されたタスク分析とローカルmDNSサービス発見の機能を必要とする場合に最適です。","ko":"구조화된 작업 분석 및 로컬 mDNS 서비스 발견 기능이 필요한 개발 에이전트에게 완벽합니다.","es":"Perfecto para agentes de desarrollo que necesitan análisis de tareas estructuradas y capacidades de descubrimiento de servicios mDNS locales.","fr":"Parfait pour les agents de développement ayant besoin d''une analyse de tâches structurée et de capacités de découverte de services mDNS locaux.","de":"Perfekt für Entwicklungsmittel, die eine strukturierte Aufgabenanalyse und lokale mDNS-Diensterkennungsfunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de análise de tarefas estruturada e capacidades de descoberta de serviço mDNS local.","ru":"Идеально подходит для агентов разработки, которым требуется структурированный анализ задач и возможности локального обнаружения сервисов mDNS.","ar":"مثالي للوكلاء التطويين الذين يحتاجون إلى تحليل مهام منظم وسمات اكتشاف الخدمة mDNS المحلية."},"recommendation":{"en":"Empowers agents to systematically break down tasks into understandable components using crates like `koi-mdns` and `koi-common`, facilitating comprehensive content analysis and transport layer involvement.","zh":"使能够代理系统地将任务分解为可理解的组件，使用像`koi-mdns`和`koi-common`这样的库，促进全面内容分析和传输层参与。","ja":"エージェントがタスクを理解可能なコンポーネントに体系的に分解できるようにし、`koi-mdns`や`koi-common`などのクレートを使用して、包括的なコンテンツ分析とトランスポート層の関与を促進します。","ko":"에이전트가 작업을 이해할 수 있는 구성 요소로 체계적으로 분해할 수 있도록 하며, `koi-mdns` 및 `koi-common`과 같은 라이브러리를 사용하여 포괄적인 내용 분석 및 전송 계층 참여를促进합니다.","es":"Habilita a los agentes a descomponer sistemáticamente las tareas en componentes comprensibles utilizando crates como `koi-mdns` y `koi-common`, lo que facilita un análisis de contenido integral y la participación en la capa de transporte.","fr":"Permet aux agents de décomposer systématiquement les tâches en composants compréhensibles en utilisant des crates comme `koi-mdns` et `koi-common`, ce qui facilite une analyse de contenu complète et l''implication de la couche de transport.","de":"Ermöglicht es den Mitteln, Aufgaben systematisch in verständliche Komponenten zu zerlegen, indem sie crates wie `koi-mdns` und `koi-common` verwenden, was eine umfassende Inhaltsanalyse und die Beteiligung an der Transportebene erleichtert.","pt":"Habilita os agentes a quebrar tarefas de forma sistemática em componentes compreensíveis usando crates como `koi-mdns` e `koi-common`, facilitando uma análise abrangente de conteúdo e envolvimento da camada de transporte.","ru":"Наделяет агентов возможностью систематически разбивать задачи на понятные компоненты с использованием таких crates, как `koi-mdns` и `koi-common`, что облегчает всесторонний анализ содержания и участие транспортного уровня.","ar":"يمنح الوكلاء القدرة على تفكيك المهام بشكل منظم إلى مكونات يمكن فهمها باستخدام الحزم مثل `koi-mdns` و `koi-common`، مما يسهل تحليل المحتوى الشامل والاشتراك في層 النقل."},"useCases":{"en":["Analyzing task requirements","Identifying involved crates and layers","Discovering local mDNS services"],"zh":["分析任务需求","识别涉及的库和层","发现本地mDNS服务"],"ja":["タスク要件の分析","関与するクレートとレイヤーの特定","ローカルmDNSサービスの発見"],"ko":["작업 요구 사항 분석","관련 라이브러리 및 계층 식별","로컬 mDNS 서비스 발견"],"es":["Análisis de los requisitos de la tarea","Identificación de los crates y capas involucrados","Descubrimiento de servicios mDNS locales"],"fr":["Analyse des exigences de la tâche","Identification des crates et couches impliqués","Découverte de services mDNS locaux"],"de":["Analyse der Aufgabenanforderungen","Identifizierung der beteiligten crates und Ebenen","Entdeckung lokaler mDNS-Dienste"],"pt":["Analisar requisitos de tarefas","Identificar crates e camadas envolvidas","Descobrir serviços mDNS locais"],"ru":["Анализ требований задач","Определение задействованных crates и слоев","Обнаружение локальных сервисов mDNS"],"ar":["تحليل متطلبات المهام","تحديد الحزم والطبقات المشاركة","اكتشاف خدمات mDNS المحلية"]},"limitations":{"en":["Requires completion of all steps before production code implementation","Specific to local mDNS service discovery"],"zh":["需要在生产代码实现之前完成所有步骤","仅限本地mDNS服务发现"],"ja":["生産コードの実装前にすべてのステップを完了する必要がある","ローカルmDNSサービス発見に特有"],"ko":["생산 코드 구현 전에 모든 단계를 완료해야 함","로컬 mDNS 서비스 발견에เฉพาะ함"],"es":["Requiere la finalización de todos los pasos antes de la implementación del código de producción","Específico para el descubrimiento de servicios mDNS locales"],"fr":["Nécessite la finalisation de toutes les étapes avant la mise en œuvre du code de production","Spécifique à la découverte de services mDNS locaux"],"de":["Erfordert die Fertigstellung aller Schritte vor der Implementierung des Produktionscodes","Spezifisch für die Erkennung lokaler mDNS-Dienste"],"pt":["Exige a conclusão de todas as etapas antes da implementação do código de produção","Específico para a descoberta de serviços mDNS local"],"ru":["Требует завершения всех шагов перед реализацией производственного кода","Специфичен для локального обнаружения сервисов mDNS"],"ar":["يتطلب إكمال جميع الخطوات قبل تنفيذ رمز الإنتاج","محدد لاكتشاف خدمات mDNS المحلية"]},"version":3},"contentHash":"27206e323e2ea1811659ed31a031b634e61f279727f4d7f03bf156542d7dd840","qualityScore":34}');
