INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ripgraphics/authorsinfo/state-management-expert', 'state-management-expert', 'ripgraphics', 'authorsinfo', 'community', 'state-management-expert ripgraphics authorsinfo community 状态管理专家是AI智能代理的一部分，帮助开发者高效管理应用状态 ステート管理エキスパートは、AIエージェントの一部で、アプリケーションの状態を効率的に管理するのに役立ちます 상태 관리 전문가는 AI 에이전트의 일부로 개발자가 애플리케이션 상태를 효율적으로 관리하도록 도와줍니다 El experto en gestión de estado utiliza AI Agentes para optimizar la gestión de estado en proyectos de desarrollo de software L''expert en gestion d''état utilise les Agents IA pour optimiser la gestion d''état dans les projets de développement de logiciels Der State-Management-Experte nutzt AI-Tools, um die Zustandsverwaltung in Software-Entwicklungsprojekten zu optimieren O especialista em gerenciamento de estado é uma ferramenta avançada para gerenciar estados em projetos como o New Author''s Info Эксперт по управлению состоянием - это продвинутый инструмент для управления состояниями в проектах, таких как New Author''s Info خبير إدارة الحالة هو أداة متقدمة لإدارة الحالات في المشاريع مثل New Author''s Info New Author''s Info Project 如何使用AI智能代理 状态管理工具比较 React状态管理最佳实践 AI智能代理安装 状态管理专家设置指南 AI智能代理与传统状态管理工具对比 New Author''s Info Project');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('frodeste/rubic2tripletex/convex-migration', 'community', 'frodeste', 'rubic2tripletex', 'frodeste/rubic2tripletex', 'convex-migration', 0, 0, 34, '2026-03-04T13:07:01.845Z', '2026-03-04T14:47:56.780Z', '8f01e252a73a493f99ca7ee51a32e85395bee333053fad5e31ad130ff1a14ab1', '{"id":"frodeste/rubic2tripletex/convex-migration","name":"convex-migration","description":{"zh":"convex-migration是一个开源的数据集成工具，用于将Rubic和Tripletex的数据进行同步和整合，实现数据的一致性和可靠性","ja":"convex-migrationは、RubicとTripletexのデータを同期して整合することで、データの一貫性と信頼性を実現するオープンソースのデータ統合ツールです","ko":"convex-migration은 Rubic와Tripletex의 데이터를 동기화하고 통합하여 데이터의 일관성과 신뢰성을 실현하는 오픈소스의 데이터 통합 도구입니다","es":"Convex Migration es un repositorio para integrar datos entre Rubic y Tripletex, utilizando tecnologías de AI Agent para desarrolladores","fr":"Convex Migration est un référentiel pour intégrer des données entre Rubic et Tripletex, en utilisant des technologies d''Agents d''IA pour les développeurs","de":"Convex Migration ist ein Repository zur Integration von Daten zwischen Rubic und Tripletex, unter Verwendung von KI-Tools für Entwickler","pt":"A Convex Migration é uma solução de integração de dados para Rubic e Tripletex, utilizando tecnologias de IA para simplificar o processo.","ru":"Convex Migration - это решение для интеграции данных между Rubic и Tripletex, использующее технологии ИИ для упрощения процесса.","ar":"Convex Migration هو حل لتكامل البيانات بين روبيك وتريبلتكس، يستخدم تكنولوجيا الذكاء الاصطناعي لتسهيل العملية.","en":"A repo for making data integration between Rubic and Tripletex"},"seo":{"title":{"zh":"convex-migration AI工具 - Rubic和Tripletex数据集成","ja":"convex-migration AIエージェント - RubicとTripletexのデータ統合","ko":"convex-migration AI 에이전트 - Rubic와Tripletex 데이터 통합","es":"Herramientas de AI: Convex Migration para Rubic y Tripletex","fr":"Outils d''IA: Convex Migration pour