INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DaccordProject/daccord/spring-clean', 'spring-clean', 'DaccordProject', 'daccord', 'community', 'spring-clean DaccordProject daccord community spring-clean是一个免费、开源的聊天应用，用于社区建设，具有高可定制性和扩展性。基于Node.js和React构建 spring-cleanはコミュニティ向けの無料・オープンソースチャットアプリです。高可定制性と拡張性を備えています。Node.jsとReactで構築されています spring-clean은 커뮤니티를 위한 무료 오픈소스 채팅 애플리케이션으로 높은 사용자 정의 및 확장성을 제공합니다. Node.js와 React로 구축되었습니다 spring-clean es una app de chat de código abierto para comunidades, diseñada para ser gratuita y accesible spring-clean est une application de chat open source pour les communautés, conçue pour être gratuite et accessible spring-clean ist eine kostenlose, Open-Source-Chat-App für Communities, die für die kostenlose Nutzung konzipiert wurde O spring-clean é uma ferramenta de IA open-source para comunidades, oferecendo um app de chat gratuito e personalizável Spring-clean - это бесплатный ИИ Агент с открытым исходным кодом для сообществ, предлагающий бесплатное приложение чата spring-clean هو أداة ذكاء اصطناعي مفتوحة المصدر للمجتمعات، يقدم تطبيق دردشة مجاني ويمكن تخصيصه A free, open-source chat app for communities. 如何使用spring-clean spring-clean教程 spring-clean替代品 spring-clean和其他聊天应用的比较 spring-clean安装 spring-clean设置指南 AI聊天应用 社区建设工具 A free, open-source chat app for communities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('verygoodmurph/figma-plugin-starter/figma-plugin', 'community', 'verygoodmurph', 'figma-plugin-starter', 'verygoodmurph/figma-plugin-starter', 'figma-plugin', 0, 0, 34, '2026-03-03T17:45:57Z', '2026-03-04T03:50:17.522Z', 'a9314fed4926c767d4aabc9dc532a108d5b0a2cb64a833d4a961d63dc5e6b512', '{"id":"verygoodmurph/figma-plugin-starter/figma-plugin","name":"figma-plugin","description":{"zh":"Figma插件配置文件，为您的GitHub配置提供AI智能体解决方案","ja":"Figmaプラグインの設定ファイルは、GitHubの設定ファイル用のAIエージェントソリューションです","ko":"피그마 플러그인 구성 파일은 GitHub 구성 파일을 위한 AI 에이전트 솔루션을 제공합니다","es":"El plugin de Figma para GitHub te permite configurar tu perfil de manera eficiente. Configuración de archivos para tu perfil de GitHub.","fr":"Le plugin Figma pour GitHub vous permet de configurer votre profil de manière efficace. Configuration de fichiers pour votre profil GitHub.","de":"Das Figma-Plugin für GitHub ermöglicht es Ihnen, Ihr Profil effizient zu konfigurieren. Konfiguration von Dateien für Ihr GitHub-Profil.","pt":"O Figma Plugin é uma ferramenta de IA para desenvolvedores que melhora a produtividade no GitHub. Aprenda a configurar e usar essa ferramenta.","ru":"Плагин Figma - это инструмент ИИ для разработчиков, который улучшает производительность в GitHub. Научитесь настраивать и использовать этот инструмент.","ar":"بلوجين فيجما هو أداة ذكاء اصطناعي للمطورين التي تحسن الإنتاجية على جيت هاب. تعلم كيفية تكوين واستخدام هذه الأداة.","en":"Config files for my GitHub profile."},"seo":{"title":{"zh":"AI智能体Figma插件配置","ja":"AIエージェントのFigmaプラグイン設定","ko":"AI 에이전트 Figma 플러그인 구성","es":"Herramientas de AI: Figma Plugin para configuración de Gi...","fr":"Outils d''IA: Figma Plugin pour la configuration de GitHub","de":"KI-Tools: Figma-Plugin für GitHub-Konfiguration","pt":"Ferramentas de IA: Figma Plugin para GitHub","ru":"ИИ Агенты: Figma Plugin для GitHub","ar":"أدوات الذكاء الاصطناعي: فيجما بلوجين لجيت هاب","en":"figma-plugin"},"description":{"zh":"Figma插件配置文件，为您的GitHub配置提供AI智能体解决方案","ja":"Figmaプラグインの設定ファイルは、GitHubの設定ファイル用のAIエージェントソリューションです","ko":"피그마 플러그인 구성 파일은 GitHub 구성 파일을 위한 AI 에이전트 솔루션을 제공합니다","es":"El plugin de Figma para GitHub te permite configurar tu perfil de manera eficiente. Configuración de archivos para tu perfil de GitHub.","fr":"Le plugin Figma pour GitHub vous permet de configurer votre profil de manière efficace. Configuration de fichiers pour votre profil GitHub.","de":"Das Figma-Plugin für GitHub ermöglicht es Ihnen, Ihr Profil effizient zu konfigurieren. Konfiguration von Dateien für Ihr GitHub-Profil.","pt":"O Figma Plugin é uma ferramenta de IA para desenvolvedores que melhora a produtividade no GitHub. Aprenda a configurar e usar essa ferramenta.","ru":"Плагин Figma - это инструмент ИИ для разработчиков, который улучшает производительность в GitHub. Научитесь настраивать и использовать этот инструмент.","ar":"بلوجين فيجما هو أداة ذكاء اصطناعي للمطورين التي تحسن الإنتاجية على جيت هاب. تعلم كيفية تكوين واستخدام هذه الأداة.","en":"Config files for my GitHub profile."},"definition":{"en":"Config files for my GitHub profile."},"features":{"zh":["支持Figma插件配置文件的创建和管理","提供GitHub配置文件的AI智能体解决方案","支持多种配置文件格式","提供代码补全和语法高亮功能","支持配置文件的版本控制"],"ja":["Figmaプラグイン設定ファイルの作成と管理をサポート","GitHub設定ファイル用のAIエージェントソリューションを提供","複数の設定ファイル形式をサポート","コード補完とシンタックスハイライト機能を提供","設定ファイルのバージョン管理をサポート"],"ko":["피그마 플러그인 구성 파일의 생성 및 관리를 지원","GitHub 구성 파일을 위한 AI 에이전트 솔루션을 제공","여러 가지 구성 파일 형식을 지원","코드 자동 완성 및 구문 강조 기능을 제공","구성 파일의 버전 관리를 지원"],"es":["Configuración de archivos para GitHub","Integración con Figma","Automatización de tareas de configuración","Mejora de la eficiencia del flujo de trabajo","Compatibilidad con múltiples plataformas"],"fr":["Configuration de fichiers pour GitHub","Intégration avec Figma","Automatisation des tâches de configuration","Amélioration de l''efficacité du flux de travail","Compatibilité avec plusieurs plateformes"],"de":["Konfiguration von Dateien für GitHub","Integration mit Figma","Automatisierung von Konfigurationsaufgaben","Verbesserung der Effizienz des Arbeitsflusses","Kompatibilität mit mehreren Plattformen"],"pt":["Configuração de arquivos para GitHub","Melhoria da produtividade com ferramentas de IA","Integração com o Figma","Suporte a desenvolvedores","Fácil instalação e configuração"],"ru":["Настройка файлов для GitHub","Повышение производительности с помощью инструментов ИИ","Интеграция с Figma","Поддержка разработчиков","Легкая установка и настройка"],"ar":["تكوين الملفات لجيت هاب","تحسين الإنتاجية باستخدام أدوات الذكاء الاصطناعي","التكامل مع فيجما","دعم المطورين","تثبيت وضبط سهل"]},"keywords":{"zh":["如何使用Figma插件","什么是Figma插件配置","Figma插件配置文件","GitHub配置文件AI智能体","Figma插件设置指南","Figma插件安装教程","Figma插件配置最佳实践"],"ja":["Figmaプラグインの使い方","Figmaプラグイン設定とは","Figmaプラグイン設定ファイル","GitHub設定ファイルのAIエージェント","Figmaプラグイン設定ガイド","Figmaプラグインのインストール方法","Figmaプラグイン設定のベストプラクティス"],"ko":["피그마 플러그인의 사용 방법","피그마 플러그인 구성이란","피그마 플러그인 구성 파일","GitHub 구성 파일의 AI 에이전트","피그마 플러그인 설정 가이드","피그마 플러그인 설치 방법","피그마 플러그인 구성의 베스트 프랙티스"],"es":["cómo usar Figma plugin","qué es Figma plugin","Figma plugin alternativa","Figma plugin vs Sketch","instalación de Figma plugin","guía de configuración de Figma plugin","desarrollo de plugins para Figma","herramientas de AI para desarrollo"],"fr":["comment utiliser le plugin Figma","quoi est le plugin Figma","alternative au plugin Figma","plugin Figma vs Sketch","installation du plugin Figma","guide de configuration du plugin Figma","développement de plugins pour Figma","outils d''IA pour le développement"],"de":["wie man Figma-Plugin verwendet","was ist Figma-Plugin","Figma-Plugin-Alternative","Figma-Plugin vs Sketch","Installation von Figma-Plugin","Konfigurationsanleitung für Figma-Plugin","Entwicklung von Plugins für Figma","KI-Tools für die Entwicklung"],"pt":["como usar Figma Plugin","o que é Figma Plugin","Figma Plugin alternativa","Figma Plugin vs Adobe XD","instalar Figma Plugin","guia de configuração do Figma Plugin"],"ru":["как использовать плагин Figma","что такое плагин Figma","плагин Figma альтернатива","плагин Figma vs Adobe XD","установить плагин Figma","руководство по настройке плагина Figma"],"ar":["كيفية استخدام بلوجين فيجما","ما هو بلوجين فيجما","بلوجين فيجما بديل","بلوجين فيجما مقابل أدوبي إكس دي","تثبيت بلوجين فيجما","دليل تكوين بلوجين فيجما"]}},"owner":"verygoodmurph","repo":"figma-plugin-starter","repoPath":"verygoodmurph/figma-plugin-starter","stars":0,"forks":0,"updatedAt":"2026-03-03T17:45:57Z","topics":["ai-enabled","figma-plugin"],"category":"community","skillMd":{"name":"figma-plugin","description":">","bodyPreview":"# Figma Plugin Development\n\nYou are an expert Figma plugin developer. This starter template is a zero-build-step Figma plugin scaffold. Your job is to help users go from idea to working plugin.\n\n## Rules & Patterns\n\nAll rules (ES5 syntax, two-context boundary, pitfalls) are in **CLAUDE.md** (always loaded).\nAll code patterns (API recipes, theming, manifest fields) are in **AGENTS.md** — read it before implementing.\n\n## Workflow\n\nFollow the phase that matches what the user is asking for. If they","body":"# Figma Plugin Development\n\nYou are an expert Figma plugin developer. This starter template is a zero-build-step Figma plugin scaffold. Your job is to help users go from idea to working plugin.\n\n## Rules & Patterns\n\nAll rules (ES5 syntax, two-context boundary, pitfalls) are in **CLAUDE.md** (always loaded).\nAll code patterns (API recipes, theming, manifest fields) are in **AGENTS.md** — read it before implementing.\n\n## Workflow\n\nFollow the phase that matches what the user is asking for. If they have a new idea with no spec, start at Phase 1. If they already have a SPEC.md filled out, skip to Phase 2. If they want to add a feature to an existing plugin, go to Phase 3.\n\n---\n\n### Phase 1: Spec Out the Plugin\n\nUse this when the user has a plugin idea but no specification yet.\n\n**Goal:** Produce a complete `SPEC.md` that''s detailed enough to build from.\n\n1. Read the current `SPEC.md`, `code.js`, `ui.html`, and `manifest.json` to understand the starting point.\n\n2. Interview the user. Ask focused questions across these areas — skip anything already obvious from context:\n   - **Core purpose:** What does the plugin do? What problem does it solve?\n   - **Target workflow:** What''s the user''s step-by-step interaction with the plugin?\n   - **UI layout:** What controls, displays, or panels does the plugin need? Approximate dimensions?\n   - **Figma API surface:** Which Figma APIs are needed? (selection, variables, styles, text, nodes, etc.)\n   - **Data flow:** What data moves between code.js and ui.html? What message types are needed?\n   - **External dependencies:** Does it need network access? What domains?\n   - **Edge cases:** What happens with empty selection, wrong node types, missing fonts, large documents?\n   - **Persistence:** Does it need to store data? (clientStorage for user prefs, pluginData for per-node data)\n\n3. Ask questions iteratively — follow up on answers, don''t dump everything at once. Stop when you have enough to build.\n\n4. Write the complete specification to `SPEC.md` with these sections:\n\n```markdown\n# [Plugin Name] — Specification\n\n## Overview\nOne paragraph describing what the plugin does and why.\n\n## Features\nNumbered list of everything the plugin does.\n\n## UI Layout\nDescription of the interface. Include dimensions (width x height).\nDescribe each section, control, and interactive element.\n\n## Architecture\n\n### Message Passing Protocol\nTable of all message types:\n| Direction | Type | Data | Purpose |\n|-----------|------|------|---------|\n\n### Code Context (code.js)\nWhat the plugin thread does: event listeners, API calls, data processing.\n\n### UI Context (ui.html)\nWhat the UI does: rendering, user interaction, message sending.\n\n## Figma API Usage\nWhich APIs are used and why.\n\n## Manifest Configuration\nAny changes needed to manifest.json (permissions, capabilities, domains).\n\n## Edge Cases & Error Handling\nHow to handle each failure mode.\n\n## Accessibility\nKeyboard navigation, ARIA labels, focus management.\n```\n\n---\n\n### Phase 2: Build From Spec\n\nUse this when `SPEC.md` is filled out and the user wants to build the plugin.\n\n**Goal:** Transform the starter template into a working plugin matching the spec.\n\n1. Read `SPEC.md` thoroughly. Read `AGENTS.md` for API patterns and best practices.\n\n2. Plan the implementation: message types, API calls, UI components, build order.\n\n3. Update `manifest.json` — name, id, editorType, permissions, capabilities, allowedDomains.\n\n4. Implement `code.js` — showUI, event listeners, message handlers, API calls, error handling.\n\n5. Implement `ui.html` — HTML structure, Figma CSS tokens, interactivity, message passing, loading/error states.\n\n6. Validate:\n   - Every message type in the spec has a sender AND receiver\n   - Every Figma API call is wrapped in try-catch\n   - Selection is checked before accessing `selection[0]`\n   - Fonts are loaded before setting text\n   - UI works in both light and dark theme\n   - No `?.` or `??` in code.js\n\n---\n\n### Phase 3: Add a Feature\n\nUse this when the user wants to add functionality to an existing plugin.\n\n1. Read the current `code.js`, `ui.html`, and `manifest.json` to understand what exists.\n\n2. Discuss the feature with the user: what it does, how it''s triggered, what APIs it needs, any new message types.\n\n3. Create a `SPEC-FEATURE-<NAME>.md` file documenting the feature (kebab-case name).\n\n4. Implement: add message types to both contexts, new UI elements, new API calls with error handling, update manifest if needed.\n\n5. Verify the feature works without breaking existing functionality.\n"},"lastSynced":"2026-03-04T03:50:17.522Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced UI design and prototyping capabilities with Figma plugins","zh":"适合需要高级 UI 设计和原型设计功能的前端代理，特别是使用 Figma 插件","ja":"Figma プラグインを使用した高度な UI デザインとプロトタイピング機能が必要なフロントエンドエージェントに最適","ko":"피그마 플러그인을 사용한 고급 UI 디자인 및 프로토타이핑 기능이 필요한 프론트엔드 에이전트에 적합","es":"Perfecto para agentes Frontend que necesitan capacidades de diseño y prototipado de interfaz de usuario avanzadas con plugins de Figma","fr":"Parfait pour les agents Frontend ayant besoin de capacités de conception et de prototypage d''interface utilisateur avancées avec des plugins Figma","de":"Perfekt für Frontend-Agenten, die erweiterte Benutzeroberflächen-Design- und Prototyping-Funktionen mit Figma-Plugins benötigen","pt":"Perfeito para Agentes Frontend que necessitam de capacidades avançadas de design de UI e prototipagem com plugins do Figma","ru":"Идеально подходит для Фронтенд-Агентов, которым необходимы расширенные возможности проектирования UI и создания прототипов с помощью плагинов Figma","ar":"مثالي لوكلات الواجهة الأمامية التي تحتاج إلى قدرات متقدمة في تصميم واجهة المستخدم وإنشاء النماذج الأولية باستخدام إضافات Figma"},"recommendation":{"en":"Empowers agents to develop and deploy custom Figma plugins using ES5 syntax, leveraging API recipes and theming capabilities outlined in AGENTS.md, while avoiding common pitfalls detailed in CLAUDE.md","zh":"使代理能够使用 ES5 语法开发和部署自定义 Figma 插件，利用 API 食谱和主题功能，如 AGENTS.md 中所述，同时避免 CLAUDE.md 中详细说明的常见陷阱","ja":"エージェントが ES5 構文を使用してカスタム Figma プラグインを開発および展開できるようにし、API レシピおよび AGENTS.md に概説されているテーミング機能を活用し、CLAUDE.md に記載されている一般的な落とし穴を回避する","ko":"에이전트가 ES5 구문을 사용하여 사용자 지정 피그마 플러그인을 개발 및 배포할 수 있도록 하여 API 레시피 및 AGENTS.md에 정리된 테마 기능을 활용하고 CLAUDE.md에 자세히 설명된 일반적인 함정 피하기","es":"Habilita a los agentes a desarrollar y desplegar plugins personalizados de Figma utilizando la sintaxis ES5, aprovechando las recetas de API y las capacidades de tematización descritas en AGENTS.md, mientras evita las trampas comunes detalladas en CLAUDE.md","fr":"Permet aux agents de développer et de déployer des plugins Figma personnalisés en utilisant la syntaxe ES5, en exploitant les recettes d''API et les capacités de thématisation décrites dans AGENTS.md, tout en évitant les pièges courants détaillés dans CLAUDE.md","de":"Ermächtigt Agenten, benutzerdefinierte Figma-Plugins mit ES5-Syntax zu entwickeln und bereitzustellen, indem API-Rezepte und Thematisierungsfunktionen wie in AGENTS.md beschrieben genutzt werden, während gemeine Fallstricke wie in CLAUDE.md detailliert vermieden werden","pt":"Capacita os agentes a desenvolver e implementar plugins personalizados do Figma usando a sintaxe ES5, aproveitando as receitas de API e capacidades de temática delineadas no AGENTS.md, evitando ao mesmo tempo as armadilhas comuns detalhadas no CLAUDE.md","ru":"Позволяет агентам разрабатывать и развертывать пользовательские плагины Figma с использованием синтаксиса ES5, используя рецепты API и возможности тематизации, изложенные в AGENTS.md, избегая при этом распространенных ошибок, подробно описанных в CLAUDE.md","ar":"يمكن الوكلاء من تطوير ونشر إضافات Figma مخصصة باستخدام بناء جملة ES5، والاستفادة من وصفات واجهة برمجة التطبيقات (API) وإمكانيات تحديد السمات الموضحة في ملف AGENTS.md، مع تجنب المزالق الشائعة المفصلة في ملف CLAUDE.md"},"useCases":{"en":["Developing custom Figma plugins for specific design tasks","Automating repetitive design workflows using Figma''s API","Creating custom UI components and themes for Figma projects"],"zh":["为特定设计任务开发自定义 Figma 插件","使用 Figma 的 API 自动化重复的设计工作流程","为 Figma 项目创建自定义 UI 组件和主题"],"ja":["特定設計タスク用のカスタム Figma プラグインを開発する","Figma の API を使用して繰り返し設計ワークフローを自動化する","Figma プロジェクト用のカスタム UI コンポーネントおよびテーマを作成する"],"ko":["특정 디자인 작업을 위한 사용자 지정 피그마 플러그인 개발","피그마의 API를 사용하여 반복적인 디자인 워크플ロー 자동화","피그마 프로젝트를 위한 사용자 지정 UI 구성 요소 및 테마 생성"],"es":["Desarrollar plugins personalizados de Figma para tareas de diseño específicas","Automatizar flujos de trabajo de diseño repetitivos utilizando la API de Figma","Crear componentes y temas de interfaz de usuario personalizados para proyectos de Figma"],"fr":["Développer des plugins Figma personnalisés pour des tâches de conception spécifiques","Automatiser les flux de travail de conception répétitifs en utilisant l''API Figma","Créer des composants et des thèmes d''interface utilisateur personnalisés pour les projets Figma"],"de":["Entwickeln benutzerdefinierter Figma-Plugins für bestimmte Designtasks","Automatisieren wiederkehrender Designtasks mithilfe der Figma-API","Erstellen benutzerdefinierter Benutzeroberflächenkomponenten und -themen für Figma-Projekte"],"pt":["Desenvolvimento de plugins personalizados do Figma para tarefas de design específicas","Automatização de fluxos de trabalho de design repetitivos usando a API do Figma","Criação de componentes de UI e temas personalizados para projetos do Figma"],"ru":["Разработка пользовательских плагинов Figma для конкретных задач проектирования","Автоматизация повторяющихся рабочих процессов проектирования с использованием API Figma","Создание пользовательских компонентов UI и тем для проектов Figma"],"ar":["تطوير إضافات Figma مخصصة لمهام التصميم المحددة","أتمتة سير عمل التصميم المتكررة باستخدام واجهة برمجة تطبيقات Figma","إنشاء مكونات وسمات واجهة مستخدم مخصصة لمشاريع Figma"]},"limitations":{"en":["Requires knowledge of ES5 syntax and Figma plugin development","Must adhere to two-context boundary rules","Limited to Figma plugin development only"],"zh":["需要 ES5 语法和 Figma 插件开发知识","必须遵守双重上下文边界规则","仅限 Figma 插件开发"],"ja":["ES5 構文および Figma プラグイン開発の知識が必要","二重コンテキスト境界規則に従う必要がある","Figma プラグイン開発のみに限定される"],"ko":["ES5 구문 및 피그마 플러그인 개발 지식이 필요","이중 컨텍스트 경계 규칙을 따라야 함","피그마 플러그인 개발만으로 제한됨"],"es":["Requiere conocimiento de la sintaxis ES5 y el desarrollo de plugins de Figma","Debe cumplir con las reglas de límite de dos contextos","Limitado solo al desarrollo de plugins de Figma"],"fr":["Nécessite une connaissance de la syntaxe ES5 et du développement de plugins Figma","Doit respecter les règles de limite de deux contextes","Limité uniquement au développement de plugins Figma"],"de":["Benötigt Kenntnisse der ES5-Syntax und der Figma-Plugin-Entwicklung","Muss den Zwei-Kontext-Grenzregeln entsprechen","Begrenzt auf die Figma-Plugin-Entwicklung"],"pt":["Requer conhecimento da sintaxe ES5 e do desenvolvimento de plugins do Figma","Deve aderir às regras de limite de dois contextos","Limitado apenas ao desenvolvimento de plugins do Figma"],"ru":["Требует знания синтаксиса ES5 и разработки плагинов Figma","Необходимо соблюдать правила границы двух контекстов","Ограничивается только разработкой плагинов Figma"],"ar":["يتطلب معرفة ببناء جملة ES5 وتطوير إضافات Figma","يجب الالتزام بقواعد حدود السياق المزدوج","يقتصر على تطوير إضافات Figma فقط"]},"version":3},"contentHash":"a9314fed4926c767d4aabc9dc532a108d5b0a2cb64a833d4a961d63dc5e6b512","qualityScore":34}');
